


const OTHER_VAL='__other__';
function money(n){return 'Rs '+Number(n||0).toLocaleString('en-PK')}
function compactK(n){const v=Number(n||0);if(Math.abs(v)>=1000000)return (v/1000).toLocaleString('en-PK',{maximumFractionDigits:1})+'K';if(Math.abs(v)>=1000)return (v/1000).toLocaleString('en-PK',{maximumFractionDigits:1})+'K';return String(Math.round(v))}
function escapeHtml(s){return String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toYMD(d){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function todayStr(){return toYMD(new Date())} function monthKeyOf(s){return s.slice(0,7)} function yearKeyOf(s){return s.slice(0,4)}
function fmtDate(s){return new Date(s+'T00:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})}
function fmtMonthLabel(mk){const [y,m]=mk.split('-');return new Date(+y,+m-1,1).toLocaleDateString('en-GB',{month:'long',year:'numeric'})}
const state={token:localStorage.getItem('labbrain_token')||localStorage.getItem('roznamcha_token')||null,user:null,view:'today',locations:[],selectedLocation:'all',selectedUser:'all',categories:[],employees:[],vendors:[],doctors:[],customLists:[],specialCards:[],staff:[],employeeProfiles:[],employeeDetails:{},fixedExpenseCategories:[],settingsSearch:{employees:'',accounts:'',locations:'',categories:'',doctors:'',vendors:'',customLists:'',specialCards:'',fixedCategories:'',financeProfiles:'',financeLoans:''},settingsEmployeeLocation:'all',settingsAccountRole:'all',settingsAccountLocation:'all',financeMonth:monthKeyOf(todayStr()),financePanel:'input',financeProfileLocation:'all',financeProfileSearch:'',financeLoanLocation:'all',financeLoanSearch:'',financeFixedLocation:'all',financeFixedSearch:'',financeSalaryLocation:'all',financeExpenseLocation:'all',financeVendorLocation:'all',financeReferralLocation:'all',financeDashboardLocation:'all',financeData:null,financePendingSalaryInclusions:{},currentDate:todayStr(),entriesCache:{},handover:null,online:0,modal:null,toast:null,reportMonth:monthKeyOf(todayStr()),reportMode:'month',reportDate:todayStr(),reportRangeFrom:monthKeyOf(todayStr())+'-01',reportRangeTo:todayStr(),reportLocations:['all'],reportLocation:'all',reportUser:'all',reportPanel:'overview',reportSubpage:'overview',aiFrom:monthKeyOf(todayStr())+'-01',aiTo:todayStr(),aiLocation:'all',aiLoading:false,aiResult:null,reportRevenueCategory:'all',reportExpenseCategory:'all',reportExpensePerson:'all',reportDetailFrom:monthKeyOf(todayStr())+'-01',reportDetailTo:monthKeyOf(todayStr())+'-'+String(dayCountInMonth(monthKeyOf(todayStr()))).padStart(2,'0'),entryManagerLocation:'all',entryManagerCategory:'all',patientCount:0,patientCountEntered:false,manualRefund:0,onlineEntries:[],manualRefundEntries:[],ameenEntries:[],ameenPayments:[],ameenPendingList:[],loading:true,loginError:null};
async function api(path,method,body){const headers={'Content-Type':'application/json'};if(state.token)headers.Authorization='Bearer '+state.token;const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),15000);try{const res=await fetch(path,{method:method||'GET',headers,body:body?JSON.stringify(body):undefined,signal:controller.signal});if(res.status===401){doLogout(false);throw new Error('Session expired — please log in again.')}const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||'Something went wrong');return data}catch(e){if(e.name==='AbortError')throw new Error('Server did not respond. Please refresh and try again.');throw e}finally{clearTimeout(timer)}}
function showToast(msg,isErr){state.toast={msg,isErr};render();setTimeout(()=>{state.toast=null;render()},2500)}
async function tryResume(){if(!state.token)return false;try{state.user=(await api('/api/me')).user;return true}catch(e){state.token=null;localStorage.removeItem('labbrain_token');localStorage.removeItem('roznamcha_token');return false}}
window.doLogin=async function(){const username=document.getElementById('loginUser').value.trim(),password=document.getElementById('loginPass').value;try{const d=await api('/api/login','POST',{username,password});state.token=d.token;state.user=d.user;localStorage.setItem('labbrain_token',state.token);localStorage.removeItem('roznamcha_token');state.loading=true;render();await loadEverything()}catch(e){state.loginError=e.message;render()}}
function doLogout(r=true){state.token=null;state.user=null;localStorage.removeItem('labbrain_token');localStorage.removeItem('roznamcha_token');if(r)render()} window.logout=()=>doLogout();
function isManagementUser(){return state.user?.role==='admin'||state.user?.role==='reviewer'}
function staffDateEditable(date){if(isManagementUser())return true;const now=new Date();const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Karachi',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(now);const get=k=>parts.find(p=>p.type===k)?.value;const today=`${get('year')}-${get('month')}-${get('day')}`;if(date===today)return true;const d=new Date(today+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-1);const prev=d.toISOString().slice(0,10);return date===prev&&Number(get('hour'))===0&&Number(get('minute'))<=30}
async function loadConfig(){const c=await api('/api/config');state.locations=c.locations||[];state.categories=c.categories||[];state.employees=c.employees||[];state.vendors=c.vendors||[];state.doctors=c.doctors||[];state.customLists=c.customLists||[];state.specialCards=c.specialCards||[];state.staff=c.staff||[];state.employeeProfiles=c.employeeProfiles||[];state.fixedExpenseCategories=c.fixedExpenseCategories||[];if(!isManagementUser())state.selectedLocation=state.user.locationId||'all'}
function locationName(id){const l=state.locations.find(x=>x.id===id);return l?l.name:'—'}
function activeCategories(){return state.categories.filter(c=>(c.locationId||'nmdc-main')===state.selectedLocation)}
async function loadMonth(mk,username,locationId){let q='';if(isManagementUser()&&username&&username!=='all')q+='&username='+encodeURIComponent(username);if(isManagementUser()&&locationId&&locationId!=='all')q+='&locationId='+encodeURIComponent(locationId);state.entriesCache[mk]=(await api('/api/entries?month='+mk+q)).entries;return state.entriesCache[mk]}
async function loadDayData(date){
  const username=isManagementUser()?state.selectedUser:state.user.username;
  await loadMonth(monthKeyOf(date),username,isManagementUser()?state.selectedLocation:undefined);
  const special=await api('/api/special-entries?date='+date+'&username='+encodeURIComponent(username||'all')+'&locationId='+encodeURIComponent(isManagementUser()?state.selectedLocation:'all'));
  state.onlineEntries=special.onlineEntries||[];state.manualRefundEntries=special.manualRefundEntries||[];state.ameenEntries=special.ameenEntries||[];state.ameenPayments=special.ameenPayments||[];state.genericSpecialEntries=special.genericSpecialEntries||{};state.genericSpecialPayments=special.genericSpecialPayments||{};state.online=Number(special.legacyOnline||0);state.manualRefund=Number(special.legacyRefund||0);
  if(!isManagementUser()){state.handover=(await api('/api/handover?date='+date)).handover;state.online=(await api('/api/online?date='+date)).amount||0;state.manualRefund=(await api('/api/manual-refund?date='+date)).amount||0;const pd=await api('/api/patients?date='+date);state.patientCount=Number(pd.count||0);state.patientCountEntered=!!pd.hasCount}
  else {state.handover=null;state.online=0;state.manualRefund=0;
    const users=state.staff.filter(u=>u.role==='staff'&&(!state.selectedLocation||state.selectedLocation==='all'||u.locationId===state.selectedLocation));
    if(username&&username!=='all') { const pd=await api('/api/patients?date='+date+'&username='+encodeURIComponent(username)); state.patientCount=Number(pd.count||0); state.patientCountEntered=!!pd.hasCount; state.handover=(await api('/api/handover?date='+date+'&username='+encodeURIComponent(username))).handover; }
    else { const vals=await Promise.all(users.map(u=>api('/api/patients?date='+date+'&username='+encodeURIComponent(u.username)).then(x=>Number(x.count||0)))); state.patientCount=vals.reduce((a,b)=>a+b,0); state.patientCountEntered=false; state.handover=null; }
  }
}
async function loadEverything(){await loadConfig();await loadDayData(state.currentDate);state.loading=false;render()}
function catById(id){if(id==='__ameen__')return{id:'__ameen__',name:'Ameen',type:'income',linkedList:'none',locationId:null};return state.categories.find(c=>c.id===id)||{id,name:id,type:'expense',linkedList:'none',locationId:'nmdc-main'}}
function listForCategory(c){if(c.linkedList==='employees')return state.employees;if(c.linkedList==='vendors')return state.vendors;if(c.linkedList==='doctors')return state.doctors;if((c.linkedList||'').startsWith('custom:'))return (state.customLists.find(x=>('custom:'+x.id)===c.linkedList)||{}).items||[];return []}
function linkedListLabel(c){if(c.linkedList==='employees')return 'Employee';if(c.linkedList==='vendors')return 'Vendor';if(c.linkedList==='doctors')return 'Doctor';if((c.linkedList||'').startsWith('custom:')){const x=state.customLists.find(x=>('custom:'+x.id)===c.linkedList);return x?.name||'List item'}return ''}
function summarize(entries){let income=0,expense=0;const byCat={};entries.forEach(e=>{const c=catById(e.catId);byCat[e.catId]=byCat[e.catId]||{name:c.name,type:c.type,total:0};byCat[e.catId].total+=Number(e.amount||0);if(c.type==='income')income+=Number(e.amount||0);else expense+=Number(e.amount||0)});return{income,expense,byCat}}
function specialTotals(){const online=Number(state.online||0)+state.onlineEntries.reduce((a,e)=>a+Number(e.amount||0),0);const refund=Number(state.manualRefund||0)+state.manualRefundEntries.reduce((a,e)=>a+Number(e.amount||0),0);const ameenVisible=specialCardVisible('ameen');const ameen=ameenVisible?state.ameenEntries.reduce((a,e)=>a+Number(e.amount||0),0):0;const ameenPending=ameenVisible?state.ameenEntries.reduce((a,e)=>a+Number(e.pending||0),0):0;const ameenCashDeduction=ameenPending;const paid=ameenVisible?state.ameenPayments.reduce((a,e)=>a+Number(e.amount||0),0):0;const bookingById={};state.ameenEntries.forEach(r=>bookingById[r.id]=r);const sameUserSameDayReceived=ameenVisible?state.ameenPayments.reduce((a,p)=>{const r=bookingById[p.ameenId];return a+(r&&r.date===p.date&&r.username===p.username?Number(p.amount||0):0)},0):0;return{online,refund,ameen,ameenPending,ameenCashDeduction,paid,sameUserSameDayReceived}}
function specialCardVisible(id){const c=(state.specialCards||[]).find(x=>x.id===id);if(!c||c.active===false)return false;return isManagementUser()?(state.selectedLocation==='all'||(c.assignedLocationIds||[]).includes(state.selectedLocation)):(c.assignedLocationIds||[]).includes(state.user.locationId)}
function genericCards(){return (state.specialCards||[]).filter(c=>c.active!==false&&c.behavior==='generic_due_receipt'&&((isManagementUser()&&state.selectedLocation==='all')||(!isManagementUser()&&c.assignedLocationIds||[]).includes(state.user.locationId)||(isManagementUser()&&state.selectedLocation!=='all'&&(c.assignedLocationIds||[]).includes(state.selectedLocation))));}
function genericCardTotals(cardId){const rows=state.genericSpecialEntries?.[cardId]||[],payments=state.genericSpecialPayments?.[cardId]||[];const due=rows.reduce((a,r)=>a+Number(r.amount||0),0),pending=rows.reduce((a,r)=>a+Number(r.pending||0),0),paid=payments.reduce((a,p)=>a+Number(p.amount||0),0);const same=payments.reduce((a,p)=>{const r=rows.find(x=>x.id===p.bookingId);return a+(r&&r.date===p.date&&r.username===p.username?Number(p.amount||0):0)},0);return{due,pending,paid,same};}
function allGenericCashAdjustments(){let pending=0,received=0,same=0;genericCards().forEach(c=>{const t=genericCardTotals(c.id);pending+=t.pending;received+=t.paid;same+=t.same});return{pending,received,same};}

function render(){const app=document.getElementById('app');if(!state.token||!state.user){app.innerHTML=renderLogin();return}if(state.loading){app.innerHTML='<div class="loading">Loading Lab-Brain…</div>';return}app.innerHTML=renderBrand()+(state.view==='today'?renderToday():state.view==='reports'&&isManagementUser()?renderReports():state.view==='settings'?renderSettings():state.view==='specialLedgers'?renderSpecialLedgers():state.view==='finance'&&isManagementUser()?renderFinance():renderToday())+(state.modal?renderModal():'')+(state.toast?`<div class="toast ${state.toast.isErr?'err':''}">${escapeHtml(state.toast.msg)}</div>`:'')+'<div class="disclosure">Lab-Brain — secure server-side records. Existing records are preserved during normal updates.</div>'}
window.setView=async function(view){if(!['today','reports','settings','specialLedgers','finance'].includes(view))view='today';if(view==='reports'&&!isManagementUser())return;if(view==='specialLedgers'&&!state.user)return;if(view==='settings'&&!state.user)return;if(view==='finance'&&!isManagementUser())return;state.view=view;state.modal=null;render();if(view==='reports'&&isManagementUser()){await loadReportBody()}if(view==='specialLedgers'){await loadSpecialLedger()}if(view==='finance'&&isManagementUser()){await loadFinance()}};
function renderLogin(){return `<div class="login-wrap"><div class="login-card"><div class="login-title">Lab-Brain</div><div class="hint" style="margin-bottom:20px;">Daily cash management — log in to continue</div><div class="field"><label>Username</label><input type="text" id="loginUser" onkeydown="if(event.key==='Enter')doLogin()"></div><div class="field"><label>Password</label><input type="password" id="loginPass" onkeydown="if(event.key==='Enter')doLogin()"></div>${state.loginError?`<div class="warning" style="margin-bottom:12px;">${escapeHtml(state.loginError)}</div>`:''}<button class="btn" style="width:100%;" onclick="doLogin()">Log in</button></div></div>`}
function renderBrand(){const loc=isManagementUser()?(state.selectedLocation==='all'?'All locations':locationName(state.selectedLocation)):locationName(state.user.locationId);const roleLabel=state.user.role==='admin'?'Admin':state.user.role==='reviewer'?'Reviewer':'Staff';const settingsTab=`<button class="${state.view==='settings'?'active':''}" onclick="setView('settings')">Settings</button>`;const reportsTab=isManagementUser()?`<button class="${state.view==='reports'?'active':''}" onclick="setView('reports')">Reports</button>`:'';const specialTab=`<button class="${state.view==='specialLedgers'?'active':''}" onclick="setView('specialLedgers')">Special Ledgers</button>`;const financeTab=isManagementUser()?`<button class="${state.view==='finance'?'active':''}" onclick="setView('finance')">Salary & Fixed Expenses</button>`:'';return `<div class="brand"><div class="brand-left"><div><div class="brand-name">Lab-Brain</div><div class="brand-sub">Daily Cash Management System &nbsp;|&nbsp; ${escapeHtml(loc)}</div></div></div><div class="brand-meta"><nav class="tabs"><button class="${state.view==='today'?'active':''}" onclick="setView('today')">Today</button>${specialTab}${reportsTab}${financeTab}${settingsTab}</nav><div class="who"><div class="who-avatar">${escapeHtml((state.user.name||'U').slice(0,1).toUpperCase())}</div><div><div class="name">${escapeHtml(state.user.name)}</div><div class="role">${roleLabel}</div></div><button class="linklike" onclick="logout()">Log out</button></div></div></div>`}
function renderToday(){const mk=monthKeyOf(state.currentDate),entries=(state.entriesCache[mk]||[]).filter(e=>e.date===state.currentDate&& (isManagementUser()?(state.selectedLocation==='all'||e.locationId===state.selectedLocation)&&(state.selectedUser==='all'||e.username===state.selectedUser):e.username===state.user.username));const s=summarize(entries),closed=!!(state.handover&&state.handover.closedAt),isToday=state.currentDate===todayStr(),editable=staffDateEditable(state.currentDate),cats=isManagementUser()?(state.selectedLocation==='all'?[]:activeCategories()):activeCategories(),incomeCats=cats.filter(c=>c.type==='income'),expenseCats=cats.filter(c=>c.type==='expense'),sp=specialTotals();
function tile(c){const t=s.byCat[c.id]?.total||0;return `<button class="tile ${c.type}" ${editable?'':'disabled'} onclick="openModal('${c.id}')"><span class="tname">${escapeHtml(c.name)}</span><span class="ttoday">${t?money(t):'Rs 0'}</span></button>`}
const normalRows=entries.map(e=>{const c=catById(e.catId);const who=e.enteredByName||e.person||'—';return `<tr class="${c.type}-row"><td>${new Date(e.ts).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</td><td><div>${escapeHtml(c.name)}</div>${c.linkedList&&c.linkedList!=='none'&&e.person?`<div class="entry-sub-detail">${escapeHtml(e.person)}</div>`:''}</td><td>${escapeHtml(who)}</td><td class="amt">${c.type==='income'?'+':'−'} ${money(e.amount)}</td><td>${escapeHtml(e.note)}</td><td>${editable?`<button class="del-btn" onclick="removeEntry('${e.id}')">Remove</button>`:''}</td></tr>`}).join('');
const onlineRows=state.onlineEntries.map(e=>`<tr class="income-row"><td>${new Date(e.ts).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</td><td>Online</td><td>${escapeHtml(e.enteredByName||e.transferor||'—')}</td><td class="amt pos">+ ${money(e.amount)}</td><td>${escapeHtml((e.note||'')+(e.note?' | ':'')+'Lab/Remarks')}</td><td>${editable?`<button class="del-btn" onclick="removeSpecialEntry('online','${e.id}')">Remove</button>`:''}</td></tr>`).join('');
const refundRows=state.manualRefundEntries.map(e=>`<tr class="expense-row"><td>${new Date(e.ts).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</td><td>Manual Refund</td><td>${escapeHtml(e.enteredByName||e.patientName||'—')}</td><td class="amt neg">− ${money(e.amount)}</td><td>${escapeHtml([e.labNo,e.note].filter(Boolean).join(' | '))}</td><td>${editable?`<button class="del-btn" onclick="removeSpecialEntry('refund','${e.id}')">Remove</button>`:''}</td></tr>`).join('');
const ameenRows=state.ameenEntries.map(e=>`<tr class="expense-row"><td>${new Date(e.ts).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</td><td>Ameen Booking / Due</td><td>${escapeHtml(e.enteredByName||'—')}</td><td class="amt neg">− ${money(e.amount)}</td><td>${escapeHtml(e.note||'')} ${e.pending>0?`<span class="hint">(Pending ${money(e.pending)})</span>`:'<span class="hint">(Cleared)</span>'}</td><td>${editable&&(e.paid===0||isManagementUser())?`<button class="del-btn" onclick="removeAmeen('${e.id}')">Remove</button>`:''}</td></tr>`).join('');
const genericRows=genericCards().map(c=>(state.genericSpecialEntries[c.id]||[]).map(e=>`<tr class="expense-row"><td>${new Date(e.ts).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</td><td>${escapeHtml(c.name)} Booking / Due</td><td>${escapeHtml(e.enteredByName||e.name||'—')}</td><td class="amt neg">− ${money(e.amount)}</td><td>${escapeHtml(e.note||'')} ${e.pending>0?`<span class="hint">(Pending ${money(e.pending)})</span>`:'<span class="hint">(Cleared)</span>'}</td><td>${editable&&(e.paid===0||isManagementUser())?`<button class="del-btn" onclick="removeGenericBooking('${c.id}','${e.id}')">Remove</button>`:''}</td></tr>`).join('')).join('');
const genericPaymentRows=genericCards().map(c=>{const rows=state.genericSpecialPayments?.[c.id]||[];return rows.map(e=>`<tr class="income-row"><td>${new Date(e.ts).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</td><td>${escapeHtml(c.name)} Receipt</td><td>${escapeHtml(e.name||e.username||'—')}</td><td class="amt pos">+ ${money(e.amount)}</td><td>Against ${fmtDate(e.bookingDate)} ${escapeHtml(e.bookingNote||'')}${e.note?` | ${escapeHtml(e.note)}`:''}</td><td>${editable?`<button class="del-btn" onclick="removeGenericPayment('${c.id}','${e.bookingId||e.id}','${e.id}')">Remove</button>`:''}</td></tr>`).join('')}).join('');
const paymentRows=state.ameenPayments.map(e=>`<tr class="income-row"><td>${new Date(e.ts).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</td><td>Ameen Receipt</td><td>${escapeHtml(e.name||e.username||'—')}</td><td class="amt pos">+ ${money(e.amount)}</td><td>Against ${fmtDate(e.bookingDate)} Ameen${e.bookingNote?` — ${escapeHtml(e.bookingNote)}`:''}${e.note?` | ${escapeHtml(e.note)}`:''}</td><td>${editable?`<button class="del-btn" onclick="removeAmeenPayment('${e.ameenId}','${e.id}')">Remove</button>`:''}</td></tr>`).join('');
const rows=(normalRows+onlineRows+refundRows+ameenRows+genericRows+paymentRows+genericPaymentRows)||'<tr class="muted-row"><td colspan="6">No entries for this date.</td></tr>';
const gc=allGenericCashAdjustments();const expected=s.income-sp.online-sp.refund-s.expense-sp.ameenCashDeduction+sp.paid-sp.sameUserSameDayReceived-gc.pending+gc.received-gc.same;const locPick=isManagementUser()?`<div class="admin-tools"><select onchange="changeLocation(this.value)"><option value="all" ${state.selectedLocation==='all'?'selected':''}>All locations</option>${state.locations.map(l=>`<option value="${l.id}" ${state.selectedLocation===l.id?'selected':''}>${escapeHtml(l.name)}</option>`).join('')}</select><select onchange="changeUser(this.value)"><option value="all" ${state.selectedUser==='all'?'selected':''}>All users</option>${state.staff.filter(u=>u.role==='staff'&&(state.selectedLocation==='all'||u.locationId===state.selectedLocation)).map(u=>`<option value="${escapeHtml(u.username)}" ${state.selectedUser===u.username?'selected':''}>${escapeHtml(u.name)}</option>`).join('')}</select></div>`:'';
const adminInfo=isManagementUser()&&state.selectedLocation==='all'?'<div class="info" style="margin-bottom:14px">Select a location above to view and enter its daily categories. Consolidated management figures are available in Reports.</div>':'';
const specialDisabled=(editable&&(!isManagementUser()||state.selectedLocation!=='all'))?'':'disabled';
return `<div class="page-head"><div><h1 class="page-title">Daily Cash Management</h1><div class="page-subtitle">Enter today’s revenue, expenses and cash details</div>${locPick}</div><div class="date-tools"><label>Date</label><input type="date" value="${state.currentDate}" onchange="changeDate(this.value)"><button class="btn-today" onclick="changeDate('${todayStr()}')">Today</button></div></div>${!isManagementUser()&&closed?'<div class="badge closed" style="margin-bottom:14px">Day closed — current date can still be corrected</div>':''}${!editable?'<div class="badge closed" style="margin-bottom:14px">Previous date — Admin/Reviewer correction only</div>':(!isManagementUser()&&!isToday?'<div class="badge closed" style="margin-bottom:14px">After-hours correction window is open until 00:30 Pakistan time.</div>':'')}${adminInfo}
<div class="layout"><div class="main-stack">${isManagementUser()&&state.selectedLocation==='all'?'':`<div class="card section-card"><div class="section-head income"><div class="section-title-left"><span class="section-icon">▣</span><span>Income — Tests / Services</span></div><span class="section-total">Total: ${money(s.income)}</span></div><div class="tile-grid">${incomeCats.map(tile).join('')}${(editable&&specialCardVisible('ameen')&&(!isManagementUser()||state.selectedLocation!=='all'))?`<button class="tile income" onclick="openSpecialModal('ameenReceipt')"><span class="tname">Ameen Receipt</span><span class="ttoday">${money(sp.paid)}</span><span class="hint">Cash received against an existing Ameen due</span></button>`:''}${genericCards().map(c=>{const t=genericCardTotals(c.id);return editable&&(!isManagementUser()||state.selectedLocation!=='all')?`<button class="tile income" onclick="openGenericReceipt('${c.id}')"><span class="tname">${escapeHtml(c.name)} Receipt</span><span class="ttoday">${money(t.paid)}</span><span class="hint">Cash received against existing ${escapeHtml(c.name)} due</span></button>`:''}).join('')}${incomeCats.length?'':'<span class="hint">No income categories for this location.</span>'}</div><div class="section-head expense" style="margin-top:15px"><div class="section-title-left"><span class="section-icon">↳</span><span>Expenses paid out</span></div><span class="section-total">Total: ${money(s.expense)}</span></div><div class="tile-grid expense-grid">${expenseCats.map(tile).join('')||'<span class="hint">No expense categories for this location.</span>'}</div></div>`}
<div class="card"><div class="section-head purple"><div class="section-title-left"><span class="section-icon">♟</span><span>Patient & Refund Entries</span></div></div><div class="tile-grid special-grid"><button class="tile" ${(isManagementUser()?state.selectedUser!=='all':true)&&editable?'':'disabled'} onclick="${(isManagementUser()?state.selectedUser!=='all':true)&&editable?'openSpecialModal(\'patients\')':'return false'}"><span class="tname">Patient Count</span><span class="ttoday">${Number(state.patientCount||0).toLocaleString('en-PK')}</span></button><button class="tile income" ${specialDisabled} onclick="openSpecialModal('online')"><span class="tname">Online</span><span class="ttoday">${money(sp.online)}</span></button><button class="tile expense" ${specialDisabled} onclick="openSpecialModal('refund')"><span class="tname">Manual Refund</span><span class="ttoday">${money(sp.refund)}</span></button>${specialCardVisible('ameen')?`<button class="tile expense" ${specialDisabled} onclick="openSpecialModal('ameen')"><span class="tname">Ameen Booking / Due</span><span class="ttoday neg">− ${money(sp.ameenPending)}</span><span class="hint">Booking is not revenue; physical cash not received</span><span class="hint">Pending: ${money(sp.ameenPending)}</span></button>`:''}${genericCards().map(c=>{const t=genericCardTotals(c.id);return `<button class="tile expense" ${specialDisabled} onclick="openGenericBooking('${c.id}')"><span class="tname">${escapeHtml(c.name)} Booking / Due</span><span class="ttoday neg">− ${money(t.pending)}</span><span class="hint">Booking is not revenue; physical cash not received</span><span class="hint">Pending: ${money(t.pending)}</span></button>`}).join('')}</div></div>
<div class="card"><div class="entries-head"><div class="entries-title"><span class="entries-icon">▤</span><span>${isManagementUser()?'Entries':'My entries'} — ${fmtDate(state.currentDate)}</span></div><button class="add-entry-btn" ${editable?'':'disabled'} onclick="${editable?'openModal(\''+(incomeCats[0]?.id||expenseCats[0]?.id||'')+'\')':'return false'}">＋ Add Entry</button></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>Category</th><th>Who / Vendor</th><th class="amt">Amount</th><th>Remarks</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></div>
</div><div class="side-stack"><div class="card summary-card"><div class="summary-top">▥ &nbsp; Daily Summary</div><div class="summary-body"><div class="summary-line"><span>Total Revenue</span><span class="amt pos">${money(s.income)}</span></div><div class="summary-line"><span>Online</span><span class="amt neg">− ${money(sp.online)}</span></div><div class="summary-line"><span>Manual Refund</span><span class="amt neg">− ${money(sp.refund)}</span></div><div class="summary-line"><span>Expenses</span><span class="amt neg">− ${money(s.expense)}</span></div>${specialCardVisible('ameen')?`<div class="summary-line"><span>Ameen Payment Pending</span><span class="amt neg">− ${money(sp.ameenPending)}</span></div><div class="summary-line"><span>Ameen Payment Received</span><span class="amt pos">+ ${money(sp.paid)}</span></div>`:''}${genericCards().map(c=>{const t=genericCardTotals(c.id);return `<div class="summary-line"><span>${escapeHtml(c.name)} Payment Pending</span><span class="amt neg">− ${money(t.pending)}</span></div><div class="summary-line"><span>${escapeHtml(c.name)} Payment Received</span><span class="amt pos">+ ${money(t.paid)}</span></div>`}).join('')}<div class="summary-line"><span>Patient Count</span><span class="amt">${Number(state.patientCount||0).toLocaleString('en-PK')}</span></div><div class="summary-line net"><span><strong>Expected Cash</strong></span><span class="amt"><strong>${isManagementUser()&&state.selectedLocation==='all'?'—':money(expected)}</strong></span></div></div></div><div class="card quick-card"><div class="quick-title">⚡ Quick Actions</div><button class="quick-btn primary" onclick="${editable&&incomeCats[0]?.id?'openModal(\''+incomeCats[0].id+'\')':'return false'}">＋ Add Entry</button>${isManagementUser()?`<button class="quick-btn" onclick="setView('reports')">▤ View Reports</button>`:''}<button class="quick-btn" onclick="window.printReport()">⎙ Print Summary</button></div>${!isManagementUser()||state.selectedUser!=='all'?`<div class="card"><div class="section-head blue"><div class="section-title-left"><span class="section-icon">↔</span><span>Cash handover${isManagementUser()?' — '+escapeHtml(state.staff.find(u=>u.username===state.selectedUser)?.name||state.selectedUser):''}</span></div></div>${renderHandover(s,expected,closed,editable)}</div>`:'<div class="card"><div class="section-head blue"><div class="section-title-left"><span class="section-icon">⚙</span><span>Management</span></div></div><div class="hint">Select a specific Staff account to view and correct that user’s Cash Handover.</div></div>'}<div class="tip-card"><strong>💡 Verify before closing</strong><br><br>Please verify all entries carefully before closing the day.<br><br>Accurate records help us maintain trust and better manage our resources.</div></div></div>`}
window.changeLocation=async function(v){state.selectedLocation=v;state.selectedUser='all';state.entriesCache={};await loadDayData(state.currentDate);render()}
window.changeUser=async function(v){state.selectedUser=v;state.entriesCache={};await loadDayData(state.currentDate);render()}
window.changeDate=async function(v){state.currentDate=v;await loadDayData(v);render()}
function renderHandover(s,expected,closed,editable){const h=state.handover||{};return `${closed?'<div class="badge ok" style="margin-bottom:10px">Saved ✓</div>':''}<div class="summary-line"><span>Expected Cash</span><span class="amt">${money(expected)}</span></div><div class="field" style="margin-top:12px"><label>Cash Short</label><input type="number" min="0" id="shortInput" value="${Number(h.cashShort||0)}" ${editable?'':'disabled'}></div><div class="field" style="margin-top:10px"><label>Excess Cash</label><input type="number" min="0" id="excessInput" value="${Number(h.excessCash||0)}" ${editable?'':'disabled'}></div><div class="hint" style="margin:8px 0">Expected Cash includes Online, Manual Refund and Ameen Pending deductions, plus Ameen Receipts received today. System calculates actual cash as Expected − Short + Excess.</div>${h.cashShort?`<div class="warning" style="margin-bottom:10px">Cash Short: <strong>${money(h.cashShort)}</strong>${h.remark?` — ${escapeHtml(h.remark)}`:''}</div>`:''}${h.excessCash?`<div class="info" style="margin-bottom:10px">Excess Cash: <strong>${money(h.excessCash)}</strong></div>`:''}<div class="field"><label>Mismatch remarks</label><input type="text" id="mismatchRemark" value="${escapeHtml(h.remark||'')}" ${editable?'':'disabled'} placeholder="e.g. Rs 500 short, amount not found"></div>${editable?`<button class="btn" style="margin-top:12px" onclick="saveHandover()">${closed?'Update handover':'Close day & hand over'}</button>`:''}`}
window.openModal=function(id){state.modal={kind:'category',catId:id};render();setTimeout(()=>document.getElementById('amountInput')?.focus(),30)};
window.openSpecialModal=async function(kind){state.modal={kind};if(kind==='ameen'||kind==='ameenReceipt'){state.ameenPendingList=[];render();try{const q=new URLSearchParams({username:'all',locationId:isManagementUser()?state.selectedLocation:'all'});const r=await api('/api/ameen/pending?'+q.toString());state.ameenPendingList=r.rows||[];if(state.modal?.kind==='ameen'||state.modal?.kind==='ameenReceipt')render()}catch(e){showToast(e.message,true)}}else{render()}setTimeout(()=>document.querySelector('#specialModal input')?.focus(),30)};
window.closeModal=function(){state.modal=null;render()};
window.openGenericBooking=function(cardId){state.modal={kind:'genericBooking',cardId};render();setTimeout(()=>document.getElementById('genericAmount')?.focus(),30)};
window.openGenericReceipt=async function(cardId){state.modal={kind:'genericReceipt',cardId};state.genericPendingList=(state.genericSpecialEntries?.[cardId]||[]).filter(x=>Number(x.pending||0)>0).map(x=>({...x}));render();try{const q=new URLSearchParams({cardId,username:isManagementUser()?state.selectedUser:'all',locationId:isManagementUser()?state.selectedLocation:'all'});const r=await api('/api/special-card-pending?'+q.toString());const serverRows=(r.bookings||[]).filter(x=>Number(x.pending||0)>0);const merged=new Map((state.genericPendingList||[]).map(x=>[x.id,x]));serverRows.forEach(x=>merged.set(x.id,x));state.genericPendingList=[...merged.values()].sort((a,b)=>String(a.date).localeCompare(String(b.date)));if(state.modal?.cardId===cardId)render()}catch(e){if(!(state.genericPendingList||[]).length)showToast(e.message,true)}};
window.submitGenericBooking=async function(mode='close'){const card=state.specialCards.find(c=>c.id===state.modal.cardId),amount=Number(document.getElementById('genericAmount')?.value||0),note=document.getElementById('genericNote')?.value.trim()||'';if(!amount||amount<=0){showToast('Enter an amount first.',true);return}const temp={id:'pending_'+Date.now(),date:state.currentDate,amount,pending:amount,paid:0,note,locationId:isManagementUser()?state.selectedLocation:state.user.locationId,username:isManagementUser()?state.selectedUser:state.user.username,name:isManagementUser()?(state.staff.find(u=>u.username===state.selectedUser)?.name||state.selectedUser):state.user.name,_pending:true};state.genericSpecialEntries=state.genericSpecialEntries||{};state.genericSpecialEntries[card.id]=[...(state.genericSpecialEntries[card.id]||[]),temp];if(mode==='close'){state.modal=null;render()}else{document.getElementById('genericAmount').value='';document.getElementById('genericNote').value='';render()}try{const r=await api('/api/special-card-booking','POST',{cardId:card.id,date:state.currentDate,amount,note,locationId:isManagementUser()?state.selectedLocation:undefined,username:isManagementUser()?state.selectedUser:undefined});const arr=state.genericSpecialEntries[card.id]||[];const i=arr.findIndex(x=>x.id===temp.id);if(i>=0)arr[i]={...r.entry,paid:0,pending:amount}}catch(e){state.genericSpecialEntries[card.id]=(state.genericSpecialEntries[card.id]||[]).filter(x=>x.id!==temp.id);render();showToast(card.name+' Booking — Not saved. '+e.message,true)}};
window.receiveGenericPayment=async function(cardId,bookingId,closeAfter=true){const amount=Number(document.getElementById('genericPayAmount')?.value||0),note=document.getElementById('genericPayNote')?.value.trim()||'';if(!amount||amount<=0){showToast('Enter payment amount.',true);return}try{const r=await api('/api/special-card-payment','POST',{cardId,bookingId,date:state.currentDate,amount,note});if(r.payment){const arr=state.genericSpecialEntries[cardId]||[],d=arr.find(x=>x.id===bookingId);if(d){d.paid=Number(d.paid||0)+Number(r.payment.amount||0);d.pending=Number(r.remaining||0)}}if(closeAfter)state.modal=null;render()}catch(e){showToast('Receipt — Not saved. '+e.message,true)}};
function renderModal(){if(state.modal.kind==='patients'||state.modal.kind==='handoverPatient')return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal" id="specialModal"><h4>${state.modal.kind==='handoverPatient'?'Enter Patient Count':'Patient Count'}</h4><div class="field"><label>Patient Count</label><input type="text" inputmode="numeric" maxlength="3" id="patientModalInput" value="" placeholder="Enter patient count" oninput="this.value=this.value.replace(/[^0-9]/g,'').slice(0,3)"></div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn" onclick="savePatientModal()">Save</button></div></div></div>`;
if(state.modal.kind==='online')return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal" id="specialModal"><h4>Online Entry</h4><div class="field"><label>Amount</label><input type="number" min="0" id="specialAmount" placeholder="0"></div><div class="field"><label>Online Transfer Person Name</label><input type="text" id="transferorInput" placeholder="Name"></div><div class="field"><label>Remarks / Lab No.</label><input type="text" id="specialNote" placeholder="e.g. Lab No. 2458"></div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn" onclick="submitSpecial('online','close')">Add</button><button class="btn secondary" onclick="submitSpecial('online','more')">Add More</button></div></div></div>`;
if(state.modal.kind==='refund')return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal" id="specialModal"><h4>Manual Refund</h4><div class="field"><label>Amount</label><input type="number" min="0" id="specialAmount" placeholder="0"></div><div class="field"><label>Patient Name</label><input type="text" id="patientNameInput" placeholder="Patient name"></div><div class="field"><label>Lab # / Slip No.</label><input type="text" id="labNoInput" placeholder="Lab or Slip No."></div><div class="field"><label>Remarks (optional)</label><input type="text" id="specialNote" placeholder="Refund detail"></div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn" onclick="submitSpecial('refund','close')">Add</button><button class="btn secondary" onclick="submitSpecial('refund','more')">Add More</button></div></div></div>`;
if(state.modal.kind==='ameenReceipt'){const pending=state.ameenPendingList||[];return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal" id="specialModal" style="max-height:90vh;overflow:auto"><h4>Ameen Receipt / Payment</h4><div class="info">Select an existing Ameen due that the customer is paying today. This payment increases physical cash but is <strong>not new revenue</strong>.</div>${pending.length?`<div class="field"><label>Pending Ameen Due</label><select id="ameenDueSelect">${pending.map(e=>`<option value="${escapeHtml(e.id)}">${fmtDate(e.date)} — Pending ${money(e.pending)} — ${escapeHtml(e.note||'No remarks')} — ${escapeHtml(e.name||e.username||'')}</option>`).join('')}</select></div><div class="field"><label>Payment Amount</label><input type="number" min="0" id="ameenPayAmount" placeholder="Enter amount"></div><div class="field"><label>Payment Remarks (optional)</label><input type="text" id="ameenPayNote" placeholder="e.g. Full payment received"></div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn" onclick="receiveAmeenPayment(true)">Receive Payment</button></div>`:'<div class="hint" style="margin-top:14px">No pending Ameen dues are available for this location.</div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Close</button></div>'}</div></div>`}if(state.modal.kind==='ameen'){return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal" id="specialModal"><h4>Ameen Booking / Due</h4><div class="info">Book a test now without physical payment. This booking is <strong>not added to Total Revenue</strong>; its pending amount is deducted from Expected Cash until the customer pays.</div><div class="field"><label>Amount</label><input type="number" min="0" id="ameenAmount" placeholder="0"></div><div class="field"><label>Remarks / Customer detail</label><input type="text" id="ameenNote" placeholder="Customer name, Lab No. or booking detail"></div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn" onclick="submitAmeen('close')">Add</button><button class="btn secondary" onclick="submitAmeen('more')">Add More</button></div></div></div>`}
if(state.modal.kind==='printHandoverReminder'){return `<div class="modal-backdrop"><div class="modal"><h4>⚠ Handover Not Closed</h4><div class="warning">Please close your Cash Handover before printing the summary. Patient Count is checked during Handover closing.</div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn" onclick="closeModal();document.getElementById('shortInput')?.scrollIntoView({block:'center'});">Close Handover</button></div></div></div>`}if(state.modal.kind==='patientCountCheck'){return `<div class="modal-backdrop"><div class="modal"><h4>⚠ Check Patient Count</h4><div class="warning">Please check the patient count. Maximum allowed is 999 patients.</div><div class="modal-actions"><button class="btn" onclick="closeModal()">OK</button></div></div></div>`}if(state.modal.kind==='accountForm'){return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><h4>Add Account</h4><div class="field"><label>Full Name</label><input id="account_name" placeholder="Full name"></div><div class="field"><label>Username</label><input id="account_username" placeholder="Username"></div><div class="field"><label>Password</label><input type="password" id="account_password" placeholder="Password"></div><div class="field"><label>Role</label><select id="account_role" onchange="document.getElementById('account_location_wrap').style.display=this.value==='staff'?'block':'none'"><option value="staff">Staff</option><option value="reviewer">Reviewer</option><option value="admin">Admin</option></select></div><div class="field" id="account_location_wrap"><label>Location</label><select id="account_location"><option value="">Select location</option>${state.locations.map(l=>`<option value="${l.id}">${escapeHtml(l.name)}</option>`).join('')}</select></div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn" onclick="saveNewAccount()">Add Account</button></div></div></div>`}
if(state.modal.kind==='employeeForm'){const name=state.modal.employee||'',p=state.employeeProfiles?.find(x=>x.employee===name)||{},d={...(state.employeeDetails?.[name]||{}),...p},view=state.modal.mode==='view';return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><h4>${state.modal.mode==='add'?'Add Employee':view?'Employee Details':'Edit Employee'}</h4><div class="field"><label>Full Name</label><input id="employee_name" value="${escapeHtml(name)}" ${view?'readonly':''} placeholder="Full name"></div><div class="field"><label>Department</label><select id="employee_department" ${view?'disabled':''}>${financeDepartmentOptions(d.department||'ALL')}</select></div><div class="field"><label>Designation</label><input id="employee_designation" value="${escapeHtml(d.designation||'')}" ${view?'readonly':''} placeholder="Designation"></div><div class="field"><label>Date of Joining</label><input type="date" id="employee_doj" value="${escapeHtml(d.dateOfJoining||'')}" ${view?'disabled':''}></div><div class="field"><label>Account Number</label><input id="employee_account" value="${escapeHtml(d.accountNumber||'')}" ${view?'readonly':''} placeholder="Account number"></div>${view?`<div class="info"><strong>Location:</strong> ${escapeHtml(locationName(d.locationId))}<br><strong>Monthly Salary:</strong> ${money(d.salary||0)}<br><strong>Status:</strong> ${d.active===false?'Inactive':'Active'}</div>`:''}<div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Close</button>${view?`<button class="btn" onclick="openEmployeeForm('${escapeHtml(name).replace(/'/g,'\\\'')}','edit')">Edit</button>`:`<button class="btn" onclick="saveEmployeeMaster()">${state.modal.mode==='add'?'Add Employee':'Save Changes'}</button>`}</div></div></div>`}
if(state.modal.kind==='loanSetup'){const emp=state.modal.employee||((state.employees||[])[0]||'');const loan=state.financeData?.employeeLoans?.[emp]||{};const amount=Number(loan.amount||0),installment=Number(loan.installment||0),paid=Number(loan.paidInstallments||0),remaining=Math.max(0,amount-paid*installment);return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><h4>Loan Setup</h4><div class="hint" style="margin-bottom:12px">Enter the employee's existing loan position. Previous paid installments are recorded so the remaining balance is clear.</div><div class="field"><label>Employee</label><select id="loan_employee" onchange="loadLoanForm(this.value)">${(state.employees||[]).map(n=>`<option value="${escapeHtml(n)}" ${n===emp?'selected':''}>${escapeHtml(n)}</option>`).join('')}</select></div><div class="field"><label>Loan Amount</label><input type="number" min="0" step="0.01" id="loan_amount" value="${amount||''}" placeholder="Total loan amount" oninput="updateLoanFormRemaining()"></div><div class="field"><label>Monthly Installment</label><input type="number" min="0" step="0.01" id="loan_installment" value="${installment||''}" placeholder="Monthly installment" oninput="updateLoanFormRemaining()"></div><div class="field"><label>Installments Already Paid</label><input type="number" min="0" step="1" id="loan_paid" value="${paid}" placeholder="0" oninput="updateLoanFormRemaining()"></div><div class="info"><strong>Remaining Loan:</strong> <span id="loan_remaining_preview">${money(remaining)}</span></div><div class="field"><label>Remarks (optional)</label><input id="loan_remarks" value="${escapeHtml(loan.remarks||'')}" placeholder="Existing loan detail"></div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Cancel</button>${amount?`<button class="btn danger" onclick="removeEmployeeLoan('${escapeHtml(emp).replace(/'/g,'\\\'')}')">Remove Loan</button>`:''}<button class="btn" onclick="saveEmployeeLoan()">Save Loan</button></div></div></div>`}
if(state.modal.kind==='genericBooking'){const c=state.specialCards.find(x=>x.id===state.modal.cardId)||{};return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal" id="specialModal"><h4>${escapeHtml(c.name||'Special')} Booking / Due</h4><div class="info">This booking is not revenue. Its pending amount reduces Expected Cash until payment is received.</div><div class="field"><label>Amount</label><input type="number" min="0" id="genericAmount" placeholder="0"></div><div class="field"><label>Remarks / Customer / Slip No.</label><input type="text" id="genericNote" placeholder="Customer, Lab No. or booking detail"></div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn" onclick="submitGenericBooking('close')">Add</button><button class="btn secondary" onclick="submitGenericBooking('more')">Add More</button></div></div></div>`}if(state.modal.kind==='genericReceipt'){const c=state.specialCards.find(x=>x.id===state.modal.cardId)||{},pending=state.genericPendingList||[];return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal" id="specialModal" style="max-height:90vh;overflow:auto"><h4>${escapeHtml(c.name||'Special')} Receipt / Payment</h4><div class="info">Select one or more pending dues. Full outstanding amounts can be received together.</div>${pending.length?`<div class="field"><label>Pending ${escapeHtml(c.name)} Dues</label><select id="genericDueSelect" onchange="document.getElementById('genericPayAmount').value=this.options[this.selectedIndex]?.dataset.pending||''">${pending.map(e=>`<option value="${escapeHtml(e.id)}" data-pending="${e.pending}">${fmtDate(e.date)} — Pending ${money(e.pending)} — ${escapeHtml(e.note||'No remarks')} — ${escapeHtml(e.name||e.username||'')}</option>`).join('')}</select></div><div class="field"><label>Payment Amount</label><input type="number" min="0" id="genericPayAmount" placeholder="Enter amount"></div><div class="field"><label>Payment Remarks (optional)</label><input type="text" id="genericPayNote" placeholder="Payment detail"></div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn" onclick="receiveGenericPayment('${escapeHtml(c.id)}',document.getElementById('genericDueSelect').value,true)">Receive Payment</button></div><div class="hint" style="margin-top:10px">For multiple dues at once, use the Special Ledger page and select multiple slips.</div>`:'<div class="hint">No pending ${escapeHtml(c.name)} dues are available.</div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Close</button></div>'}</div></div>`} 
const c=catById(state.modal.catId),list=listForCategory(c),has=!!(c.linkedList&&c.linkedList!=='none'),label=linkedListLabel(c);return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><h4>${escapeHtml(c.name)} <span style="color:var(--ink-soft);font-weight:400;font-size:13px">(${c.type})</span></h4><div class="field"><label>Amount</label><input type="number" min="0" id="amountInput" placeholder="0"></div>${has?`<div class="field"><label>${escapeHtml(label)}</label><select id="personSelect" onchange="document.getElementById('personOtherWrap').style.display=this.value==='${OTHER_VAL}'?'block':'none'"><option value="">— select —</option>${list.map(n=>`<option value="${escapeHtml(n)}">${escapeHtml(n)}</option>`).join('')}<option value="${OTHER_VAL}">Other (not in list)</option></select></div><div class="field" id="personOtherWrap" style="display:none"><label>Type ${escapeHtml(label.toLowerCase())} name</label><input type="text" id="personOtherInput"></div>`:''}<div class="field"><label>Remarks (optional)</label><input type="text" id="noteInput" placeholder="e.g. payment detail"></div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn" onclick="submitEntry('close')">Add</button><button class="btn secondary" onclick="submitEntry('more')">Add More</button></div></div></div>`}
window.submitEntry=async function(mode='close'){
  if(state.modal.kind==='genericBooking'){const c=state.specialCards.find(x=>x.id===state.modal.cardId)||{};return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal" id="specialModal"><h4>${escapeHtml(c.name||'Special')} Booking / Due</h4><div class="info">This booking is not revenue. Its pending amount reduces Expected Cash until payment is received.</div><div class="field"><label>Amount</label><input type="number" min="0" id="genericAmount" placeholder="0"></div><div class="field"><label>Remarks / Customer / Slip No.</label><input type="text" id="genericNote" placeholder="Customer, Lab No. or booking detail"></div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn" onclick="submitGenericBooking('close')">Add</button><button class="btn secondary" onclick="submitGenericBooking('more')">Add More</button></div></div></div>`}if(state.modal.kind==='genericReceipt'){const c=state.specialCards.find(x=>x.id===state.modal.cardId)||{},pending=state.genericPendingList||[];return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal" id="specialModal" style="max-height:90vh;overflow:auto"><h4>${escapeHtml(c.name||'Special')} Receipt / Payment</h4><div class="info">Select one or more pending dues. Full outstanding amounts can be received together.</div>${pending.length?`<div class="field"><label>Pending ${escapeHtml(c.name)} Dues</label><select id="genericDueSelect" onchange="document.getElementById('genericPayAmount').value=this.options[this.selectedIndex]?.dataset.pending||''">${pending.map(e=>`<option value="${escapeHtml(e.id)}" data-pending="${e.pending}">${fmtDate(e.date)} — Pending ${money(e.pending)} — ${escapeHtml(e.note||'No remarks')} — ${escapeHtml(e.name||e.username||'')}</option>`).join('')}</select></div><div class="field"><label>Payment Amount</label><input type="number" min="0" id="genericPayAmount" placeholder="Enter amount"></div><div class="field"><label>Payment Remarks (optional)</label><input type="text" id="genericPayNote" placeholder="Payment detail"></div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn" onclick="receiveGenericPayment('${escapeHtml(c.id)}',document.getElementById('genericDueSelect').value,true)">Receive Payment</button></div><div class="hint" style="margin-top:10px">For multiple dues at once, use the Special Ledger page and select multiple slips.</div>`:'<div class="hint">No pending ${escapeHtml(c.name)} dues are available.</div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Close</button></div>'}</div></div>`} 
const c=catById(state.modal.catId),amtEl=document.getElementById('amountInput'),noteEl=document.getElementById('noteInput');
  const amt=amtEl.value,note=noteEl.value;
  if(!amt||Number(amt)<=0){showToast('Enter an amount first.',true);return}
  let person='';
  if(c.linkedList&&c.linkedList!=='none'){
    const sel=document.getElementById('personSelect').value;
    if(sel===OTHER_VAL){person=document.getElementById('personOtherInput').value.trim();if(!person){showToast('Type a name, or pick from the list.',true);return}}
    else if(!sel){showToast('Please select a '+linkedListLabel(c).toLowerCase()+'.',true);return}
    else person=sel
  }
  const mk=monthKeyOf(state.currentDate);
  const context={date:state.currentDate,location:isManagementUser()?state.selectedLocation:'',username:isManagementUser()?state.selectedUser:state.user.username};
  const tempId='pending_'+Date.now().toString(36)+Math.random().toString(36).slice(2,7);
  const tempEntry={id:tempId,date:context.date,catId:c.id,amount:Number(amt),note,person,locationId:context.location,username:context.username,name:isManagementUser()?(state.staff.find(u=>u.username===context.username)?.name||context.username):state.user.name,enteredByUsername:state.user.username,enteredByName:state.user.name,ts:Date.now(),_pending:true};
  state.entriesCache[mk]=state.entriesCache[mk]||[];
  state.entriesCache[mk].push(tempEntry);
  if(mode==='close'){state.modal=null;render()}
  else{amtEl.value='';noteEl.value='';if(document.getElementById('personSelect')){document.getElementById('personSelect').value='';document.getElementById('personOtherWrap').style.display='none'}render();setTimeout(()=>document.getElementById('amountInput')?.focus(),30)}
  try{
    const r=await api('/api/entries','POST',{date:context.date,catId:c.id,amount:amt,note,person,locationId:isManagementUser()?state.selectedLocation:undefined,username:isManagementUser()?state.selectedUser:undefined});
    const current=state.entriesCache[mk]||[];
    const i=current.findIndex(e=>e.id===tempId);
    if(i>=0)current[i]=r.entry;
  }catch(e){
    state.entriesCache[mk]=(state.entriesCache[mk]||[]).filter(e=>e.id!==tempId);
    render();
    showToast(c.name+' — Not saved. '+e.message,true);
  }
};
window.savePatientModal=async function(){const raw=document.getElementById('patientModalInput').value.trim();if(raw===''){showToast('Enter Patient Count. If there were no patients, enter 0.',true);return}const v=Number(raw);if(!Number.isInteger(v)||v<0){showToast('Enter a valid whole patient count.',true);return}if(v>999){state.modal={kind:'patientCountCheck'};render();return}const old=Number(state.patientCount||0),oldEntered=!!state.patientCountEntered;state.patientCount=v;state.patientCountEntered=true;const followHandover=state.modal.kind==='handoverPatient';state.modal=null;render();try{await api('/api/patients','PUT',{date:state.currentDate,count:v,username:isManagementUser()?state.selectedUser:undefined});if(followHandover) await saveHandoverConfirmed()}catch(e){state.patientCount=old;state.patientCountEntered=oldEntered;render();showToast('Patient count — Not saved. '+e.message,true)}};
window.submitSpecial=async function(kind,mode){
  const amount=Number(document.getElementById('specialAmount').value||0);if(!Number.isFinite(amount)||amount<=0){showToast('Enter a valid amount.',true);return}
  const isOnline=kind==='online';
  let entry;
  if(isOnline){const transferor=document.getElementById('transferorInput').value.trim(),note=document.getElementById('specialNote').value.trim();if(!transferor){showToast('Enter transfer person name.',true);return}entry={id:'pending_'+Date.now().toString(36)+Math.random().toString(36).slice(2,7),date:state.currentDate,amount,note,transferor,locationId:isManagementUser()?state.selectedLocation:state.user.locationId,username:isManagementUser()?state.selectedUser:state.user.username,_pending:true};state.onlineEntries.push(entry)}
  else{const patientName=document.getElementById('patientNameInput').value.trim(),labNo=document.getElementById('labNoInput').value.trim(),note=document.getElementById('specialNote').value.trim();entry={id:'pending_'+Date.now().toString(36)+Math.random().toString(36).slice(2,7),date:state.currentDate,amount,patientName,labNo,note,locationId:isManagementUser()?state.selectedLocation:state.user.locationId,username:isManagementUser()?state.selectedUser:state.user.username,_pending:true};state.manualRefundEntries.push(entry)}
  if(mode==='close'){state.modal=null;render()}else{document.querySelectorAll('#specialModal input').forEach(i=>{i.value=''});render();setTimeout(()=>document.getElementById('specialAmount')?.focus(),30)}
  try{
    let r;if(isOnline){const transferor=entry.transferor,note=entry.note;r=await api('/api/online-entry','POST',{date:state.currentDate,amount,note,transferor,locationId:isManagementUser()?state.selectedLocation:undefined,username:isManagementUser()?state.selectedUser:undefined});const i=state.onlineEntries.findIndex(e=>e.id===entry.id);if(i>=0)state.onlineEntries[i]=r.entry}
    else{r=await api('/api/manual-refund-entry','POST',{date:state.currentDate,amount,patientName:entry.patientName,labNo:entry.labNo,note:entry.note,locationId:isManagementUser()?state.selectedLocation:undefined,username:isManagementUser()?state.selectedUser:undefined});const i=state.manualRefundEntries.findIndex(e=>e.id===entry.id);if(i>=0)state.manualRefundEntries[i]=r.entry}
  }catch(e){if(isOnline)state.onlineEntries=state.onlineEntries.filter(e=>e.id!==entry.id);else state.manualRefundEntries=state.manualRefundEntries.filter(e=>e.id!==entry.id);render();showToast((isOnline?'Online':'Manual Refund')+' — Not saved. '+e.message,true)}
};
window.submitAmeen=async function(mode){
  const amount=Number(document.getElementById('ameenAmount').value||0),note=document.getElementById('ameenNote').value.trim();if(!Number.isFinite(amount)||amount<=0){showToast('Enter a valid amount.',true);return}
  const temp={id:'pending_'+Date.now().toString(36)+Math.random().toString(36).slice(2,7),date:state.currentDate,amount,note,paid:0,pending:amount,locationId:isManagementUser()?state.selectedLocation:state.user.locationId,username:isManagementUser()?state.selectedUser:state.user.username,_pending:true};
  state.ameenEntries.push(temp);if(mode==='close'){state.modal=null;render()}else{document.getElementById('ameenAmount').value='';document.getElementById('ameenNote').value='';render();setTimeout(()=>document.getElementById('ameenAmount')?.focus(),30)}
  try{const r=await api('/api/ameen','POST',{date:state.currentDate,amount,note,locationId:isManagementUser()?state.selectedLocation:undefined,username:isManagementUser()?state.selectedUser:undefined});const i=state.ameenEntries.findIndex(e=>e.id===temp.id);if(i>=0)state.ameenEntries[i]={...r.entry,paid:0,pending:amount}}catch(e){state.ameenEntries=state.ameenEntries.filter(e=>e.id!==temp.id);render();showToast('Ameen Booking — Not saved. '+e.message,true)}
};
window.receiveAmeenPayment=async function(closeAfter=false){const id=document.getElementById('ameenDueSelect')?.value,amount=Number(document.getElementById('ameenPayAmount')?.value||0),note=document.getElementById('ameenPayNote')?.value.trim()||'';if(!id||!Number.isFinite(amount)||amount<=0){showToast('Select a due and enter payment amount.',true);return}try{const r=await api('/api/ameen/'+encodeURIComponent(id)+'/payment','POST',{date:state.currentDate,amount,note});if(r.payment){state.ameenPayments=state.ameenPayments||[];const savedPayment={...r.payment,ameenId:r.payment.ameenId||id};state.ameenPayments=[...state.ameenPayments,savedPayment];const due=state.ameenEntries.find(e=>e.id===id);if(due){due.paid=Number(due.paid||0)+Number(savedPayment.amount||0);due.pending=Number(r.remaining||0)}}if(closeAfter)state.modal=null;render();}catch(e){showToast('Ameen Receipt — Not saved. '+e.message,true)}};
window.removeSpecialEntry=async function(kind,id){if(!confirm('Remove this entry?'))return;try{const endpoint=kind==='online'?'/api/online-entry/':'/api/manual-refund-entry/';await api(endpoint+encodeURIComponent(id)+'?month='+monthKeyOf(state.currentDate),'DELETE');await loadDayData(state.currentDate);render();showToast('Entry removed.')}catch(e){showToast(e.message,true)}};
window.removeGenericBooking=async function(cardId,id){if(!confirm('Remove this booking?'))return;try{await api('/api/special-card-booking/'+encodeURIComponent(cardId)+'/'+encodeURIComponent(id)+'?month='+monthKeyOf(state.currentDate),'DELETE');await loadDayData(state.currentDate);render();showToast('Booking removed.')}catch(e){showToast(e.message,true)}};
window.removeGenericPayment=async function(cardId,bookingId,paymentId){if(!confirm('Remove this receipt? The linked due will become pending again.'))return;try{await api('/api/special-card-payment/'+encodeURIComponent(cardId)+'/'+encodeURIComponent(bookingId)+'/'+encodeURIComponent(paymentId),'DELETE');await loadDayData(state.currentDate);render();showToast('Receipt removed.')}catch(e){showToast(e.message,true)}};
window.removeAmeen=async function(id){if(!confirm('Remove this Ameen booking?'))return;try{await api('/api/ameen/'+encodeURIComponent(id)+'?month='+monthKeyOf(state.currentDate),'DELETE');await loadDayData(state.currentDate);render();showToast('Ameen booking removed.')}catch(e){showToast(e.message,true)}};
window.removeEntry=async function(id){if(!confirm('Remove this entry?'))return;try{await api('/api/entries/'+encodeURIComponent(id)+'?month='+monthKeyOf(state.currentDate),'DELETE');const mk=monthKeyOf(state.currentDate);state.entriesCache[mk]=(state.entriesCache[mk]||[]).filter(e=>e.id!==id);render();showToast('Entry removed.')}catch(e){showToast(e.message,true)}};
window.removeAmeenPayment=async function(ameenId,paymentId){if(!confirm('Remove this Ameen receipt? The linked due will become pending again.'))return;try{await api('/api/ameen/'+encodeURIComponent(ameenId)+'/payment/'+encodeURIComponent(paymentId),'DELETE');await loadDayData(state.currentDate);render();showToast('Ameen receipt removed.')}catch(e){showToast(e.message,true)}};
async function saveHandoverConfirmed(){const short=Number(document.getElementById('shortInput')?.value||0),excess=Number(document.getElementById('excessInput')?.value||0),remark=(document.getElementById('mismatchRemark')?.value||'').trim();if(short>0&&excess>0){showToast('Enter either Cash Short or Excess Cash, not both.',true);return}const payload={date:state.currentDate,cashShort:short,excessCash:excess,remark};if(isManagementUser())payload.username=state.selectedUser;try{await api('/api/handover','POST',payload);await loadDayData(state.currentDate);render();setTimeout(()=>{const badge=document.querySelector('.side-stack .badge.ok');if(badge)badge.scrollIntoView({block:'nearest'})},30)}catch(e){showToast('Handover — Not saved. '+e.message,true)}}
window.saveHandover=async function(){if(!state.patientCountEntered){state.modal={kind:'handoverPatient'};render();setTimeout(()=>document.getElementById('patientModalInput')?.focus(),30);return}await saveHandoverConfirmed()}
window.loadEntryManager=async function(){
  const el=document.getElementById('entryManager'); if(!el)return;
  el.innerHTML='<div class="loading">Loading entries…</div>';
  try{
    const {from,to}=reportRange();
    const q=new URLSearchParams({from,to,locationId:state.entryManagerLocation,username:state.reportUser});
    const d=await api('/api/management-summary?'+q.toString());
    const rows=[];
    (d.entries||[]).forEach(e=>{const c=catById(e.catId);if(state.entryManagerCategory!=='all'&&e.catId!==state.entryManagerCategory)return;rows.push({id:e.id,kind:'entry',month:state.reportMonth,date:e.date,staff:e.name||e.username,location:locationName(e.locationId),category:c.name,person:e.person||'—',amount:e.amount,note:e.note||''})});
    if(state.entryManagerCategory==='all'||state.entryManagerCategory==='__online__') (d.onlineEntries||[]).forEach(e=>rows.push({id:e.id,kind:'online',month:state.reportMonth,date:e.date,staff:e.name||e.username,location:locationName(e.locationId),category:'Online',person:e.transferor||'—',amount:e.amount,note:e.note||''}));
    if(state.entryManagerCategory==='all'||state.entryManagerCategory==='__refund__') (d.manualRefundEntries||[]).forEach(e=>rows.push({id:e.id,kind:'refund',month:state.reportMonth,date:e.date,staff:e.name||e.username,location:locationName(e.locationId),category:'Manual Refund',person:e.patientName||'—',amount:e.amount,note:[e.labNo,e.note].filter(Boolean).join(' | ')}));
    if(state.entryManagerCategory==='all'||state.entryManagerCategory==='__ameen__') (d.ameenBookings||[]).forEach(e=>rows.push({id:e.id,kind:'ameen',month:state.reportMonth,date:e.date,staff:e.name||e.username,location:locationName(e.locationId),category:'Ameen Booking / Due',person:'—',amount:e.amount,note:(e.note||'')+' | Pending '+money(e.pending)}));
    if(state.entryManagerCategory==='all'||state.entryManagerCategory==='__ameenReceipt__') (d.ameenPayments||[]).forEach(e=>rows.push({id:e.id,kind:'ameenPayment',ameenId:e.ameenId,month:state.reportMonth,date:e.date,staff:e.name||e.username,location:locationName(e.locationId),category:'Ameen Receipt',person:'—',amount:e.amount,note:'Against '+fmtDate(e.bookingDate)+(e.note?' | '+e.note:'') }));
    rows.sort((a,b)=>a.date.localeCompare(b.date)||String(a.id).localeCompare(String(b.id)));
    const catOptions=state.categories.filter(c=>c.locationId===state.entryManagerLocation||state.entryManagerLocation==='all').map(c=>`<option value="${escapeHtml(c.id)}" ${state.entryManagerCategory===c.id?'selected':''}>${escapeHtml(c.name)}</option>`).join('');
    el.innerHTML=`<div class="hint" style="margin-bottom:8px">Filter individual entries by Location and Category. The selected report month and staff filter above remain applicable.</div><div class="filters"><select onchange="setEntryManagerLocation(this.value)"><option value="all" ${state.entryManagerLocation==='all'?'selected':''}>All locations</option>${state.locations.map(l=>`<option value="${l.id}" ${state.entryManagerLocation===l.id?'selected':''}>${escapeHtml(l.name)}</option>`).join('')}</select><select onchange="setEntryManagerCategory(this.value)"><option value="all" ${state.entryManagerCategory==='all'?'selected':''}>All categories</option>${catOptions}<option value="__online__" ${state.entryManagerCategory==='__online__'?'selected':''}>Online</option><option value="__refund__" ${state.entryManagerCategory==='__refund__'?'selected':''}>Manual Refund</option><option value="__ameen__" ${state.entryManagerCategory==='__ameen__'?'selected':''}>Ameen Booking / Due</option><option value="__ameenReceipt__" ${state.entryManagerCategory==='__ameenReceipt__'?'selected':''}>Ameen Receipt</option></select><button class="btn secondary" onclick="loadEntryManager()">Apply Filter</button></div>`+
      `<table><thead><tr><th>Date</th><th>Staff</th><th>Location</th><th>Category</th><th>Person</th><th class="amt">Amount</th><th>Remarks</th><th>Delete</th></tr></thead><tbody>`+
      (rows.map(r=>`<tr><td>${fmtDate(r.date)}</td><td>${escapeHtml(r.staff)}</td><td>${escapeHtml(r.location)}</td><td>${escapeHtml(r.category)}</td><td>${escapeHtml(r.person)}</td><td class="amt">${r.kind==='refund'||r.kind==='entry'&&catById((d.entries||[]).find(x=>x.id===r.id)?.catId).type==='expense'?'−':'+'} ${money(r.amount)}</td><td>${escapeHtml(r.note)}</td><td><button class="del-btn" onclick="deleteManagedEntry('${r.kind}','${r.id}'${r.ameenId?`, '${r.ameenId}'`:''})">Remove</button></td></tr>`).join('')||'<tr class="muted-row"><td colspan="8">No entries found.</td></tr>')+
      '</tbody></table>';
  }catch(e){el.innerHTML='<div class="warning">Could not load entries. '+escapeHtml(e.message||'Please refresh.')+'</div>'}
};
window.setEntryManagerLocation=function(v){state.entryManagerLocation=v;state.entryManagerCategory='all';loadEntryManager()};
window.setEntryManagerCategory=function(v){state.entryManagerCategory=v;loadEntryManager()};
window.deleteManagedEntry=async function(kind,id,ameenId){
  if(!confirm('Remove this entry? This action permanently removes the selected transactional record.'))return;
  try{
    if(kind==='entry') await api('/api/entries/'+encodeURIComponent(id)+'?month='+state.reportMonth,'DELETE');
    else if(kind==='online') await api('/api/online-entry/'+encodeURIComponent(id)+'?month='+state.reportMonth,'DELETE');
    else if(kind==='refund') await api('/api/manual-refund-entry/'+encodeURIComponent(id)+'?month='+state.reportMonth,'DELETE');
    else if(kind==='ameen') await api('/api/ameen/'+encodeURIComponent(id)+'?month='+state.reportMonth,'DELETE');
    else if(kind==='ameenPayment') await api('/api/ameen/'+encodeURIComponent(ameenId)+'/payment/'+encodeURIComponent(id),'DELETE');
    await loadEntryManager();
    showToast('Entry removed.');
  }catch(e){showToast(e.message,true)}
};
function reportRange(){if(state.reportMode==='date'&&state.reportDate)return {from:state.reportDate,to:state.reportDate};if(state.reportMode==='range')return {from:state.reportRangeFrom,to:state.reportRangeTo};const from=state.reportMonth+'-01',to=state.reportMonth+'-'+String(dayCountInMonth(state.reportMonth)).padStart(2,'0');return {from,to}}
function reportPeriodLabel(){if(state.reportMode==='date'&&state.reportDate)return fmtDate(state.reportDate);if(state.reportMode==='range'&&state.reportRangeFrom&&state.reportRangeTo)return fmtDate(state.reportRangeFrom)+' — '+fmtDate(state.reportRangeTo);return fmtMonthLabel(state.reportMonth)}
function reportLocationQuery(q){const ids=(state.reportLocations||['all']).filter(x=>x&&x!=='all');q.set('locationIds',ids.join(','));q.set('locationId',ids.length===1?ids[0]:'all');return q}
function reportLocationLabel(){const ids=(state.reportLocations||['all']).filter(x=>x!=='all');return !ids.length?'All locations':ids.length===1?locationName(ids[0]):`${ids.length} locations selected`}
function aiSeverityIcon(level){return level==='high'?'🔴':level==='medium'?'🟡':'🔵'}
function aiAlertRow(a){return `<tr><td>${fmtDate(a.date)}</td><td>${escapeHtml(a.locationName||'—')}</td><td>${aiSeverityIcon(a.severity)} <strong>${escapeHtml(a.title||'Alert')}</strong><div class="ai-reason">${escapeHtml(a.reason||'').replace(/\n/g,'<br>')}</div></td><td>${escapeHtml(a.userName||'—')}</td><td><div class="ai-actions"><button class="btn secondary" onclick="openAiDate('${escapeHtml(a.date)}','${escapeHtml(a.locationId||'')}','${escapeHtml(a.username||'')}')">Check</button><button class="btn secondary" onclick="reviewAiAlert('${escapeHtml(a.alertKey||'')}')">✓ Review</button></div></td></tr>`}
function renderAiCheck(){const r=state.aiResult;const from=state.aiFrom||monthKeyOf(todayStr())+'-01',to=state.aiTo||todayStr();return `<div class="card ai-module"><div class="analysis-head"><div><h3>🤖 AI Activity Check</h3><div class="hint">Pattern-based review of user activity, patient count, Lab/X-ray/Ultrasound entries, branch revenue patterns, timing and unclosed handovers. It only highlights unusual records; it never changes your data.</div></div><button class="btn secondary" onclick="runAiCheck()">${state.aiLoading?'Checking…':'Run AI Check'}</button></div><div class="filters ai-filters"><label>Branch</label><select id="aiLocation" onchange="state.aiLocation=this.value"><option value="all">All Branches</option>${state.locations.map(l=>`<option value="${escapeHtml(l.id)}" ${state.aiLocation===l.id?'selected':''}>${escapeHtml(l.name)}</option>`).join('')}</select><label>From</label><input type="date" id="aiFrom" value="${escapeHtml(from)}" onchange="state.aiFrom=this.value"><label>To</label><input type="date" id="aiTo" value="${escapeHtml(to)}" onchange="state.aiTo=this.value"><button class="btn" onclick="runAiCheck()">Check</button></div><div class="ai-live card"><div><strong>Current Month Monitor</strong><div class="hint">Live-derived from current data. New entries and closed handovers are included automatically whenever the check is refreshed.</div></div><button class="btn secondary" onclick="runAiCurrentMonth()">Refresh Current Month</button></div>${r?`<div class="ai-summary"><div class="ai-kpi high"><span>High</span><strong>${r.counts.high}</strong></div><div class="ai-kpi medium"><span>Medium</span><strong>${r.counts.medium}</strong></div><div class="ai-kpi low"><span>Info</span><strong>${r.counts.low}</strong></div><div class="ai-kpi total"><span>Checked Days</span><strong>${r.checkedDays}</strong></div></div><div class="hint" style="margin:10px 0 8px">Generated ${escapeHtml(r.generatedAtLabel||'now')}. Review each highlighted date against LIS before deciding it is an error.</div>${r.alerts.length?`<div class="table-wrap"><table class="ai-table"><thead><tr><th>Date</th><th>Branch</th><th>Alert / Reason</th><th>User</th><th></th></tr></thead><tbody>${r.alerts.map(aiAlertRow).join('')}</tbody></table></div>`:`<div class="info">✓ No unusual activity was detected for the selected filters.</div>`}`:`<div class="info" style="margin-top:12px">Select a branch and date range, then click <strong>Run AI Check</strong>. Your existing 30-day history can be checked without changing any records.</div>`}</div>`}
window.openAiPage=function(){state.reportSubpage='ai';state.aiResult=null;render()};window.closeAiPage=function(){state.reportSubpage='overview';state.aiResult=null;render();loadReportBody()};window.runAiCheck=async function(){const from=document.getElementById('aiFrom')?.value||state.aiFrom,to=document.getElementById('aiTo')?.value||state.aiTo,locationId=document.getElementById('aiLocation')?.value||state.aiLocation||'all';if(!from||!to||from>to){showToast('Select a valid From and To date.',true);return}state.aiFrom=from;state.aiTo=to;state.aiLocation=locationId;state.aiLoading=true;render();try{state.aiResult=await api('/api/ai-activity-check?'+new URLSearchParams({from,to,locationId}));}catch(e){showToast('AI Check — '+e.message,true)}finally{state.aiLoading=false;render()}};window.runAiCurrentMonth=async function(){state.aiFrom=monthKeyOf(todayStr())+'-01';state.aiTo=todayStr();state.aiLocation='all';render();await runAiCheck()};window.reviewAiAlert=async function(alertKey){if(!alertKey)return;try{await api('/api/ai-activity-review','POST',{alertKey});if(state.aiResult){state.aiResult.alerts=(state.aiResult.alerts||[]).filter(a=>a.alertKey!==alertKey);state.aiResult.counts={high:state.aiResult.alerts.filter(a=>a.severity==='high').length,medium:state.aiResult.alerts.filter(a=>a.severity==='medium').length,low:state.aiResult.alerts.filter(a=>a.severity==='low').length};}render();}catch(e){showToast('Could not review this alert — '+e.message,true)}};window.openAiDate=function(date,locationId,username){const q=new URLSearchParams({aiDate:date,aiLocation:locationId||'all',aiUser:username||'all'});const w=window.open('/?'+q.toString(),'_blank');if(!w)showToast('Please allow pop-ups for the AI Check date review.',true)};
function renderReports(){if(state.reportSubpage==='ai')return `<div class="card"><div class="analysis-head"><div><h3>Reports → AI Activity Check</h3><div class="hint">Use this page to find dates and users that deserve verification against LIS.</div></div><button class="btn secondary" onclick="closeAiPage()">← Management Report</button></div></div>${renderAiCheck()}`;const selectedLocs=(state.reportLocations||['all']).filter(x=>x!=='all');return `<div class="card"><div class="filters"><strong style="margin-right:4px">Management Report</strong><button class="btn secondary no-print" onclick="openAiPage()">🤖 AI Activity Check</button><input type="month" value="${state.reportMonth}" onchange="setReportMonth(this.value)"><select onchange="setReportMode(this.value)"><option value="month" ${state.reportMode==='month'?'selected':''}>This month</option><option value="date" ${state.reportMode==='date'?'selected':''}>Specific date</option><option value="range" ${state.reportMode==='range'?'selected':''}>Date range</option></select>${state.reportMode==='date'?`<input type="date" value="${state.reportDate||todayStr()}" onchange="setReportDate(this.value)">`:state.reportMode==='range'?`<label>From</label><input type="date" value="${state.reportRangeFrom||state.reportMonth+'-01'}" onchange="state.reportRangeFrom=this.value"><label>To</label><input type="date" value="${state.reportRangeTo||todayStr()}" onchange="state.reportRangeTo=this.value"><button class="btn secondary" onclick="applyReportRange()">Apply</button>`:''}${isManagementUser()?`<details class="report-location-picker"><summary>${escapeHtml(reportLocationLabel())}</summary><div class="location-checks"><label><input type="checkbox" ${!selectedLocs.length?'checked':''} onchange="toggleReportLocation('all',this.checked)"> All locations</label>${state.locations.map(l=>`<label><input type="checkbox" value="${escapeHtml(l.id)}" ${selectedLocs.includes(l.id)?'checked':''} onchange="toggleReportLocation('${l.id}',this.checked)"> ${escapeHtml(l.name)}</label>`).join('')}<button type="button" class="btn" onclick="applyReportLocations()">Apply locations</button></div></details><select onchange="setReportUser(this.value)"><option value="all">All staff</option>${state.staff.filter(u=>u.role==='staff'&&(!selectedLocs.length||selectedLocs.includes(u.locationId))).map(u=>`<option value="${escapeHtml(u.username)}" ${state.reportUser===u.username?'selected':''}>${escapeHtml(u.name)}</option>`).join('')}</select>`:''}<button class="btn secondary no-print" onclick="downloadReportCSV()">Excel (CSV)</button><button class="btn secondary no-print" onclick="printReport()">PDF / Print</button></div><div id="reportBody" class="loading">Loading management report…</div>${isManagementUser()?`<div class="card no-print" style="margin-top:18px"><h3>Data Safety & Demo</h3><div class="hint" style="margin-bottom:10px">A downloadable backup is a complete copy of your Lab-Brain data. The system also keeps automatic snapshots before normal saves.</div><div class="row"><button class="btn secondary" onclick="downloadBackup()">Download Full Backup</button><button class="btn secondary" onclick="loadDemoData()">Load Demo Data</button><button class="btn danger" onclick="removeDemoData()">Remove Demo Data</button><button class="btn secondary" onclick="showBackups()">Backup History</button></div><div id="backupList" style="margin-top:12px"></div></div><div class="card no-print" style="margin-top:18px"><h3>Individual Entry Management</h3><div class="hint" style="margin-bottom:10px">Review and permanently delete individual transactional entries. Use the Location and Category filters below to find the required entries.</div><button class="btn secondary" onclick="loadEntryManager()">Show Entries</button><div id="entryManager" style="margin-top:12px"></div></div>`:''}</div>`}
window.setReportMode=function(v){state.reportMode=v;state.reportPanel='overview';state.reportRevenueCategory='all';state.reportExpenseCategory='all';if(v==='month'){state.reportDate=state.reportMonth+'-01';state.reportRangeFrom=state.reportMonth+'-01';state.reportRangeTo=state.reportMonth+'-'+String(dayCountInMonth(state.reportMonth)).padStart(2,'0')}else if(v==='date'&&!state.reportDate)state.reportDate=todayStr();else if(v==='range'){state.reportRangeFrom=state.reportRangeFrom||state.reportMonth+'-01';state.reportRangeTo=state.reportRangeTo||todayStr()}render();loadReportBody()};window.setReportDate=function(v){if(!v)return;state.reportMode='date';state.reportDate=v;state.reportMonth=monthKeyOf(v);state.reportRangeFrom=v;state.reportRangeTo=v;state.reportPanel='overview';state.reportRevenueCategory='all';state.reportExpenseCategory='all';state.reportDetailFrom=v;state.reportDetailTo=v;state.entryManagerLocation=state.reportLocation;state.entryManagerCategory='all';render();loadReportBody()};window.setReportMonth=function(v){state.reportMonth=v;state.reportMode='month';state.reportDate=v+'-01';state.reportRangeFrom=v+'-01';state.reportRangeTo=v+'-'+String(dayCountInMonth(v)).padStart(2,'0');state.reportPanel='overview';state.reportRevenueCategory='all';state.reportDetailFrom=v+'-01';state.reportDetailTo=v+'-'+String(dayCountInMonth(v)).padStart(2,'0');state.entryManagerLocation=state.reportLocation;state.entryManagerCategory='all';render();loadReportBody()};window.applyReportRange=function(){if(!state.reportRangeFrom||!state.reportRangeTo){showToast('Select both From and To dates.',true);return}if(state.reportRangeFrom>state.reportRangeTo){showToast('From date cannot be after To date.',true);return}state.reportMode='range';state.reportPanel='overview';loadReportBody()};window.toggleReportLocation=function(id,checked){let current=Array.isArray(state.reportLocations)?state.reportLocations:[];let ids=current.filter(x=>x&&x!=='all');const boxes=document.querySelectorAll('.location-checks input[type=checkbox]');const allBox=boxes[0];if(id==='all'){if(checked){state.reportLocations=['all'];boxes.forEach((b,i)=>{if(i>0)b.checked=false})}else{state.reportLocations=[]}return}if(checked){ids=ids.filter(x=>x!==id);ids.push(id);state.reportLocations=ids.length?ids:['all'];if(allBox)allBox.checked=false}else{ids=ids.filter(x=>x!==id);state.reportLocations=ids.length?ids:['all'];if(!ids.length&&allBox)allBox.checked=true}};window.applyReportLocations=function(){const ids=(state.reportLocations||['all']).filter(x=>x!=='all');state.reportLocation=ids.length===1?ids[0]:'all';state.reportUser='all';state.reportPanel='overview';state.reportRevenueCategory='all';state.entryManagerLocation=state.reportLocation;state.entryManagerCategory='all';render();loadReportBody()};window.setReportLocation=function(v){state.reportLocations=v==='all'?['all']:[v];state.reportLocation=v;state.reportUser='all';state.reportPanel='overview';state.reportRevenueCategory='all';state.entryManagerLocation=v;state.entryManagerCategory='all';render();loadReportBody()};window.setReportUser=function(v){state.reportUser=v;state.reportPanel='overview';state.reportRevenueCategory='all';render();loadReportBody()};window.toggleReportPanel=function(v){state.reportPanel=state.reportPanel===v?'overview':v;if(v!=='revenue')state.reportRevenueCategory='all';loadReportBody()};window.setReportRevenueCategory=function(v){state.reportRevenueCategory=v;state.reportPanel='revenue';loadReportBody()};window.openDetailedReport=function(kind){if(!['staff','mismatch'].includes(kind))return;state.reportPanel=kind;if(!state.reportDetailFrom)state.reportDetailFrom=state.reportMode==='range'?state.reportRangeFrom:state.reportMonth+'-01';if(!state.reportDetailTo)state.reportDetailTo=state.reportMode==='range'?state.reportRangeTo:state.reportMonth+'-'+String(dayCountInMonth(state.reportMonth)).padStart(2,'0');loadReportBody()};window.applyDetailedReport=function(){if(!state.reportDetailFrom||!state.reportDetailTo){showToast('Select both From and To dates.',true);return}if(state.reportDetailFrom>state.reportDetailTo){showToast('From date cannot be after To date.',true);return}loadReportBody()};function monthAdd(mk,delta){const [y,m]=mk.split('-').map(Number);const d=new Date(y,m-1+delta,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function dayCountInMonth(mk){const [y,m]=mk.split('-').map(Number);return new Date(y,m,0).getDate()}
function barSeries(values,max){return values.map(v=>{const pct=max?Math.max(0,Math.min(88,(v.value/max)*88)):0;return `<div class="vbar-wrap" style="--bar-height:${pct}%"><div class="vbar" style="height:${pct}%" title="${escapeHtml(v.label)}: ${escapeHtml(v.display)}"><span class="vbar-value">${escapeHtml(v.display)}</span></div><div class="vbar-label">${escapeHtml(v.label)}</div></div>`}).join('')}
function linearTrendForecast(values){const ys=values.map(Number).filter(Number.isFinite);if(!ys.length)return null;if(ys.length===1)return ys[0];const n=ys.length;let sx=0,sy=0,sxx=0,sxy=0;for(let i=0;i<n;i++){sx+=i;sy+=ys[i];sxx+=i*i;sxy+=i*ys[i]}const den=n*sxx-sx*sx;const slope=den?(n*sxy-sx*sy)/den:0;const intercept=(sy-slope*sx)/n;return Math.max(0,intercept+slope*n)}
async function expectedClosingForecast(metric,currentValue){if(state.reportMode!=='month'||state.reportMonth!==monthKeyOf(todayStr()))return null;const elapsed=Math.max(1,new Date().getDate()),days=dayCountInMonth(state.reportMonth),pace=Math.max(0,Number(currentValue||0))/elapsed*days;const months=[];for(let i=6;i>=1;i--)months.push(monthAdd(state.reportMonth,-i));try{const rows=await Promise.all(months.map(async mk=>{const d=await api('/api/management-summary?'+reportLocationQuery(new URLSearchParams({from:mk+'-01',to:mk+'-'+String(dayCountInMonth(mk)).padStart(2,'0'),username:state.reportUser})));return metric==='patients'?d.patients.reduce((a,x)=>a+Number(x.count||0),0):summarize(reportEntriesWithAmeen(d)).income}));const trend=linearTrendForecast(rows);const adjusted=trend!=null&&trend>0?Math.max(pace,(pace*0.65)+(trend*0.35)):pace;return{value:Math.round(Math.max(0,adjusted)),pace:Math.round(Math.max(0,pace)),trend:trend==null?null:Math.round(Math.max(0,trend))}}catch(e){console.warn('Expected closing forecast unavailable',e);return{value:Math.round(pace),pace:Math.round(pace),trend:null}}}
function reportSpecialTotals(data){const online=(data.online||[]).reduce((a,x)=>a+Number(x.amount||0),0)+(data.onlineEntries||[]).reduce((a,x)=>a+Number(x.amount||0),0);const refund=(data.manualRefunds||[]).reduce((a,x)=>a+Number(x.amount||0),0)+(data.manualRefundEntries||[]).reduce((a,x)=>a+Number(x.amount||0),0);const ameen=(data.ameenBookings||[]).reduce((a,x)=>a+Number(x.amount||0),0);const pending=(data.ameenBookings||[]).reduce((a,x)=>a+Number(x.pending||0),0);const paid=(data.ameenPayments||[]).reduce((a,x)=>a+Number(x.amount||0),0);return{online,refund,ameen,pending,paid}}
function reportEntriesWithAmeen(data){return [...(data.entries||[])]}
async function loadReportBody(){const el=document.getElementById('reportBody');if(!el)return;el.innerHTML='<div class="loading">Loading management report…</div>';try{const {from,to}=reportRange();let q=reportLocationQuery(new URLSearchParams({from,to,username:state.reportUser}));const data=await api('/api/management-summary?'+q.toString()),detailData=(state.reportPanel==='staff'||state.reportPanel==='mismatch')?await api('/api/management-summary?'+reportLocationQuery(new URLSearchParams({from:state.reportDetailFrom,to:state.reportDetailTo,username:state.reportUser}))):null,allEntries=reportEntriesWithAmeen(data),s=summarize(allEntries),sp=reportSpecialTotals(data),bookingById={};(data.ameenBookings||[]).forEach(r=>bookingById[r.id]=r);const sameUserSameDayReceived=(data.ameenPayments||[]).reduce((a,p)=>{const r=bookingById[p.ameenId];return a+(r&&r.date===p.date&&r.username===p.username?Number(p.amount||0):0)},0),expected=s.income-sp.online-sp.refund-s.expense-sp.pending+sp.paid-sameUserSameDayReceived,short=data.handovers.reduce((a,h)=>a+Number(h.cashShort||0),0),excess=data.handovers.reduce((a,h)=>a+Number(h.excessCash||0),0),patients=data.patients.reduce((a,x)=>a+Number(x.count||0),0);const prevRange=state.reportMode==='date'?(()=>{const d=new Date(state.reportDate+'T00:00:00');d.setDate(d.getDate()-1);const x=toYMD(d);return {from:x,to:x}})():state.reportMode==='range'?(()=>{const a=new Date(state.reportRangeFrom+'T00:00:00'),b=new Date(state.reportRangeTo+'T00:00:00'),days=Math.round((b-a)/86400000)+1,p=new Date(a),q=new Date(a);p.setDate(p.getDate()-days);q.setDate(q.getDate()-1);return {from:toYMD(p),to:toYMD(q)}})():(()=>{const prevMk=monthAdd(state.reportMonth,-1);const prevTo=state.reportMonth===monthKeyOf(todayStr())?Math.min(new Date().getDate(),dayCountInMonth(prevMk)):dayCountInMonth(prevMk);return {from:prevMk+'-01',to:prevMk+'-'+String(prevTo).padStart(2,'0')}})();const prevData=await api('/api/management-summary?'+reportLocationQuery(new URLSearchParams({from:prevRange.from,to:prevRange.to,username:state.reportUser}))),prevEntries=reportEntriesWithAmeen(prevData),prevRev=summarize(prevEntries).income,prevExp=summarize(prevEntries).expense,prevPatients=prevData.patients.reduce((a,x)=>a+Number(x.count||0),0);const pct=(cur,prev)=>prev?((cur-prev)/prev*100):null;let cards=[['revenue','Revenue',money(s.income),pct(s.income,prevRev)],['expense','Cash Counter Expenses',money(s.expense),pct(s.expense,prevExp)],['patients','Patient Count',patients.toLocaleString('en-PK'),pct(patients,prevPatients)]];const ameenPendingTotal=(data.ameenBookings||[]).reduce((a,x)=>a+Number(x.pending||0),0),ameenClearedTotal=(data.ameenBookings||[]).reduce((a,x)=>a+(Number(x.amount||0)-Number(x.pending||0)),0);let panel='';if(['revenue','expense','patients'].includes(state.reportPanel)){let current=[];if(state.reportPanel==='revenue')current=allEntries.filter(e=>{const c=catById(e.catId);return c.type==='income'&&(state.reportRevenueCategory==='all'||e.catId===state.reportRevenueCategory)});else if(state.reportPanel==='expense')current=allEntries.filter(e=>catById(e.catId).type==='expense');if(state.reportPanel==='patients'){const byDay={};data.patients.forEach(x=>byDay[x.date]=(byDay[x.date]||0)+Number(x.count||0));const vals=Object.keys(byDay).sort().map(d=>({value:byDay[d],label:d.slice(8),display:String(byDay[d])}));panel=`<div class="analysis card"><div class="analysis-head"><div><h3>Daily Patient Count</h3><div class="hint">${reportPeriodLabel()}</div></div><button class="icon-btn" onclick="toggleReportPanel('patients')">Close</button></div><div class="vbars">${barSeries(vals,Math.max(1,...vals.map(x=>x.value)))||'<div class="hint">No patient data.</div>'}</div><div class="trend-actions"><button class="btn secondary" onclick="showTrend('patients',3)">Last 3 Completed Months</button><button class="btn secondary" onclick="showTrend('patients',6)">Last 6 Completed Months</button></div></div>`}else{let ledger='';if(state.reportPanel==='expense'){const expenseCats=state.categories.filter(c=>c.type==='expense');const selected=expenseCats.find(c=>c.id===state.reportExpenseCategory);const people=selected?listForCategory(selected):[];if(state.reportExpensePerson!=='all')current=current.filter(e=>e.catId===state.reportExpenseCategory&&e.person===state.reportExpensePerson);else if(state.reportExpenseCategory!=='all')current=current.filter(e=>e.catId===state.reportExpenseCategory);const total=current.reduce((a,e)=>a+Number(e.amount||0),0);ledger=`<div class="card" style="margin-top:14px"><div class="analysis-head"><div><h3>Individual Expense Ledger</h3><div class="hint">Select a category, then a person to see that person’s monthly ledger.</div></div></div><div class="filters" style="margin-top:10px"><select onchange="setReportExpenseCategory(this.value)"><option value="all">All expense categories</option>${expenseCats.map(c=>`<option value="${escapeHtml(c.id)}" ${state.reportExpenseCategory===c.id?'selected':''}>${escapeHtml(c.name)}</option>`).join('')}</select>${selected&&selected.linkedList&&selected.linkedList!=='none'?`<select onchange="setReportExpensePerson(this.value)"><option value="all">All ${escapeHtml(linkedListLabel(selected))}</option>${people.map(n=>`<option value="${escapeHtml(n)}" ${state.reportExpensePerson===n?'selected':''}>${escapeHtml(n)}</option>`).join('')}</select>`:''}<span class="kpi" style="padding:8px 12px"><span class="label">Ledger Total</span> <strong>${money(total)}</strong></span></div>${state.reportExpenseCategory!=='all'?`<table><thead><tr><th>Date</th><th>Person</th><th class="amt">Amount</th><th>Remarks</th></tr></thead><tbody>${current.sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<tr><td>${fmtDate(e.date)}</td><td>${escapeHtml(e.person||'—')}</td><td class="amt neg">− ${money(e.amount)}</td><td>${escapeHtml(e.note||'')}</td></tr>`).join('')||'<tr class="muted-row"><td colspan="4">No ledger entries.</td></tr>'}</tbody></table>`:'<div class="hint">Choose an expense category to open its monthly ledger.</div>'}</div>`}
const byDay={};const byCat={};const byCatLabels={};current.forEach(e=>{byDay[e.date]=(byDay[e.date]||0)+Number(e.amount||0);const c=catById(e.catId);const key=String(c.name||'').trim().toLowerCase();byCat[key]=(byCat[key]||0)+Number(e.amount||0);if(!byCatLabels[key])byCatLabels[key]=c.name});const vals=Object.keys(byDay).sort().map(d=>({value:byDay[d],label:d.slice(8),display:state.reportPanel==='revenue'?compactK(byDay[d]):money(byDay[d])}));const catVals=Object.entries(byCat).sort((a,b)=>b[1]-a[1]).map(([key,value])=>({value,label:byCatLabels[key],display:state.reportPanel==='revenue'?compactK(value):money(value)}));const incomeCats=[];const seenIncome=new Set();state.categories.filter(c=>c.type==='income').forEach(c=>{const key=String(c.name||'').trim().toLowerCase();if(!seenIncome.has(key)){seenIncome.add(key);incomeCats.push(c)}});const catButtons=state.reportPanel==='revenue'?`<div class="category-switch"><button class="btn secondary ${state.reportRevenueCategory==='all'?'active':''}" onclick="setReportRevenueCategory('all')">All Revenue</button>${incomeCats.map(c=>`<button class="btn secondary ${state.reportRevenueCategory===c.id?'active':''}" onclick="setReportRevenueCategory('${escapeHtml(c.id)}')">${escapeHtml(c.name)}</button>`).join('')}</div>`:'';const selectedCat=state.reportPanel==='revenue'&&state.reportRevenueCategory!=='all'?catById(state.reportRevenueCategory).name:'';panel=`<div class="analysis card"><div class="analysis-head"><div><h3>${state.reportPanel==='revenue'?(selectedCat?'Daily Revenue — '+escapeHtml(selectedCat):'Daily Revenue'):'Daily Cash Counter Expenses'}</h3><div class="hint">${reportPeriodLabel()}</div></div><button class="icon-btn" onclick="toggleReportPanel('${state.reportPanel}')">Close</button></div>${catButtons}<div class="vbars">${barSeries(vals,Math.max(1,...vals.map(x=>x.value)))||'<div class="hint">No data.</div>'}</div><div class="group-label" style="margin-top:18px">${state.reportPanel==='revenue'?'Revenue by category':'Expenses by category'}</div><div class="vbars small">${barSeries(catVals,Math.max(1,...catVals.map(x=>x.value)))||'<div class="hint">No data.</div>'}</div>${state.reportMode==='month'?`<div class="trend-actions"><button class="btn secondary" onclick="showTrend('${state.reportPanel}',3)">Last 3 Completed Months</button><button class="btn secondary" onclick="showTrend('${state.reportPanel}',6)">Last 6 Completed Months</button></div>`:''}</div>${ledger}`}}const forecastRevenue=await expectedClosingForecast('revenue',s.income),forecastPatients=await expectedClosingForecast('patients',patients);const forecastHtml=forecastRevenue&&forecastPatients?`<div class="kpi-grid forecast-cards"><div class="report-card forecast"><div class="rc-label">Expected Closing (Revenue)</div><div class="rc-value">${money(forecastRevenue.value)}</div><div class="rc-change">Trend-based forecast</div><div class="rc-hint">Current pace: ${money(forecastRevenue.pace)}${forecastRevenue.trend!=null?' · Recent trend: '+money(forecastRevenue.trend):''}</div></div><div class="report-card forecast"><div class="rc-label">Expected Closing (Patient Count)</div><div class="rc-value">${forecastPatients.value.toLocaleString('en-PK')}</div><div class="rc-change">Trend-based forecast</div><div class="rc-hint">Current pace: ${forecastPatients.pace.toLocaleString('en-PK')}${forecastPatients.trend!=null?' · Recent trend: '+forecastPatients.trend.toLocaleString('en-PK'):''}</div></div></div>`:'';el.innerHTML=`<h3>${reportPeriodLabel()}</h3><div class="kpi-grid report-cards">${cards.map(([key,label,value,change])=>`<button class="report-card ${key}" onclick="toggleReportPanel('${key}')"><div class="rc-label">${label}</div><div class="rc-value">${value}</div><div class="rc-change ${change!=null?(change>=0?'up':'down'):''}">${change==null?'No previous data':(change>=0?'↑ ':'↓ ')+Math.abs(change).toFixed(1)+'% vs previous comparable period'}</div><div class="rc-hint">Click to view analysis</div></button>`).join('')}</div>${forecastHtml}<div class="kpi-grid" style="margin-top:10px"><div class="kpi"><div class="label">Online</div><div class="value">${money(sp.online)}</div></div><div class="kpi"><div class="label">Manual Refund</div><div class="value neg">${money(sp.refund)}</div></div><div class="kpi"><div class="label">Ameen Bookings</div><div class="value neg">${money(sp.ameen)}</div></div><div class="kpi"><div class="label">Ameen Payment Received</div><div class="value pos">${money(sp.paid)}</div></div><div class="kpi"><div class="label">Ameen Payment Pending</div><div class="value neg">${money(sp.pending)}</div></div><div class="kpi"><div class="label">Ameen Cleared</div><div class="value pos">${money(ameenClearedTotal)}</div></div><div class="kpi"><div class="label">Expected Cash</div><div class="value">${money(expected)}</div></div><div class="kpi"><div class="label">Cash Short</div><div class="value neg">${money(short)}</div></div><div class="kpi"><div class="label">Excess Cash</div><div class="value pos">${money(excess)}</div></div></div>${panel}<div class="group-label" style="margin-top:22px">Location performance</div><table><thead><tr><th>Location</th><th class="amt">Revenue</th><th class="amt">Cash Expenses</th><th class="amt">Patients</th></tr></thead><tbody>${locationRows(data)}</tbody></table><div class="detail-report-tools no-print"><span class="label">Detailed Reports:</span><button class="btn secondary ${state.reportPanel==='staff'?'active':''}" onclick="openDetailedReport('staff')">Staff Performance</button><button class="btn secondary ${state.reportPanel==='mismatch'?'active':''}" onclick="openDetailedReport('mismatch')">Cash Mismatch</button></div>${state.reportPanel==='staff'||state.reportPanel==='mismatch'?`<div class="card detail-report-panel no-print"><div class="analysis-head"><div><h3>${state.reportPanel==='staff'?'Staff Performance':'Cash Mismatch / Handover History'}</h3><div class="hint">Select the required date range, then apply the filter.</div></div><button class="icon-btn" onclick="toggleReportPanel('${state.reportPanel}')">Close</button></div><div class="filters"><label>From</label><input type="date" value="${state.reportDetailFrom}" onchange="state.reportDetailFrom=this.value"><label>To</label><input type="date" value="${state.reportDetailTo}" onchange="state.reportDetailTo=this.value"><button class="btn" onclick="applyDetailedReport()">Apply</button></div>${state.reportPanel==='staff'?`<table><thead><tr><th>Staff</th><th>Location</th><th class="amt">Revenue</th><th class="amt">Cash Expenses</th><th class="amt">Patients</th></tr></thead><tbody>${staffReportRows(detailData||data)}</tbody></table>`:`<table><thead><tr><th>Date</th><th>Staff</th><th>Location</th><th class="amt">Expected</th><th class="amt">Short</th><th class="amt">Excess</th><th>Remarks</th></tr></thead><tbody>${handoverRows(detailData||data)}</tbody></table>`}</div>`:''}`
}catch(e){console.error(e);el.innerHTML=`<div class="warning">Report could not be loaded. ${escapeHtml(e.message||'Please refresh and try again.')}</div>`}}
window.setReportExpenseCategory=function(v){state.reportExpenseCategory=v;state.reportExpensePerson='all';state.reportPanel='expense';loadReportBody()};window.setReportExpensePerson=function(v){state.reportExpensePerson=v;state.reportPanel='expense';loadReportBody()};
function locationRows(data){const map={};reportEntriesWithAmeen(data).forEach(e=>{const id=e.locationId||'nmdc-main';map[id]=map[id]||{rev:0,exp:0,patients:0};const c=catById(e.catId);map[id][c.type==='income'?'rev':'exp']+=Number(e.amount||0)});data.patients.forEach(x=>{const id=x.locationId||'nmdc-main';map[id]=map[id]||{rev:0,exp:0,patients:0};map[id].patients+=Number(x.count||0)});return Object.entries(map).map(([id,x])=>`<tr><td>${escapeHtml(locationName(id))}</td><td class="amt pos">${money(x.rev)}</td><td class="amt neg">${money(x.exp)}</td><td class="amt">${x.patients.toLocaleString('en-PK')}</td></tr>`).join('')||'<tr class="muted-row"><td colspan="4">No location data.</td></tr>'}
function staffReportRows(data){const map={};reportEntriesWithAmeen(data).forEach(e=>{map[e.username]=map[e.username]||{name:e.name,locationId:e.locationId,rev:0,exp:0,patients:0};const c=catById(e.catId);map[e.username][c.type==='income'?'rev':'exp']+=Number(e.amount||0)});data.patients.forEach(x=>{map[x.username]=map[x.username]||{name:x.username,locationId:x.locationId,rev:0,exp:0,patients:0};map[x.username].patients+=Number(x.count||0)});return Object.values(map).map(x=>`<tr><td>${escapeHtml(x.name)}</td><td>${escapeHtml(locationName(x.locationId))}</td><td class="amt pos">${money(x.rev)}</td><td class="amt neg">${money(x.exp)}</td><td class="amt">${x.patients.toLocaleString('en-PK')}</td></tr>`).join('')||'<tr class="muted-row"><td colspan="5">No staff data.</td></tr>'}
function handoverRows(data){return data.handovers.sort((a,b)=>a.date.localeCompare(b.date)).map(h=>`<tr><td>${fmtDate(h.date)}</td><td>${escapeHtml(h.username)}</td><td>${escapeHtml(locationName(h.locationId))}</td><td class="amt">${money(h.calculated)}</td><td class="amt neg">${money(h.cashShort)}</td><td class="amt pos">${money(h.excessCash)}</td><td>${escapeHtml(h.remark||'')}</td></tr>`).join('')||'<tr class="muted-row"><td colspan="7">No handover records.</td></tr>'}
async function downloadFile(url,filename){const headers={};if(state.token)headers.Authorization='Bearer '+state.token;const r=await fetch(url,{headers});if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(d.error||'Download failed');}const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
window.downloadReportCSV=async function(){try{const {from,to}=reportRange();const q=reportLocationQuery(new URLSearchParams({from,to,username:state.reportUser}));await downloadFile('/api/report.csv?'+q.toString(),'lab-brain-report-'+(state.reportMode==='date'?state.reportDate:state.reportMonth)+'.csv');}catch(e){showToast(e.message,true)}};
window.printReport=async function(){
  if(!isManagementUser() && !state.handover){state.modal={kind:'printHandoverReminder'};render();return;}
  if(isManagementUser() && state.selectedUser!=='all' && !state.handover){state.modal={kind:'printHandoverReminder'};render();return;}
  const old=document.querySelector('.print-summary-only');
  if(old) old.remove();
  const side=document.querySelector('.side-stack');
  const main=document.querySelector('.main-stack');
  if(!side||!main){window.print();return}
  const summary=side.querySelector('.summary-card');
  const cards=[...side.children];
  const handover=cards.find(el=>/Cash handover/i.test(el.textContent||''));
  const entries=[...main.children].find(el=>/My entries|Entries/i.test(el.textContent||'')&&el.querySelector('table'));
  if(!summary||!handover||!entries){window.print();return}
  const holder=document.createElement('div');
  holder.className='print-summary-only';
  const top=document.createElement('div');
  top.className='print-top-grid';
  top.appendChild(summary.cloneNode(true));
  top.appendChild(handover.cloneNode(true));
  const entriesClone=entries.cloneNode(true);
  entriesClone.classList.add('print-entries');
  holder.appendChild(top);
  holder.appendChild(entriesClone);
  holder.querySelectorAll('button').forEach(b=>{b.disabled=true;b.removeAttribute('onclick');});
  holder.querySelectorAll('input').forEach(i=>{i.setAttribute('readonly','readonly');});
  document.body.appendChild(holder);
  document.body.classList.add('print-summary-mode');
  const cleanup=()=>{document.body.classList.remove('print-summary-mode');if(holder&&holder.parentNode)holder.remove();window.removeEventListener('afterprint',cleanup);};
  window.addEventListener('afterprint',cleanup);
  setTimeout(()=>window.print(),50);
};
