function renderSettings(){
 const a=state.user.role==='admin';
 if(!a)return `<div class="card"><h3>My account</h3><div class="hint">Location: ${escapeHtml(locationName(state.user.locationId))}</div>${passwordCard()}</div>`;
 const loc=state.selectedLocation==='all'?((state.locations[0]||{}).id||'nmdc-main'):state.selectedLocation;
 const q=(state.settingsSearch||{});
 const esc=v=>escapeHtml(v||'');
 const profileFor=name=>(state.employeeProfiles||[]).find(p=>p.employee===name)||{};
 const detailFor=name=>({...((state.employeeDetails||{})[name]||{}),...profileFor(name),employee:name});
 const filterText=(v,needle)=>String(v||'').toLowerCase().includes(String(needle||'').trim().toLowerCase());
 const sectionSearch=(id,placeholder,key)=>`<div class="settings-search"><span>🔍</span><input id="${id}" type="search" value="${esc(q[key])}" placeholder="${placeholder}" oninput="liveSettingsSearch('${key}',this.value)"></div>`;
 const locations=state.locations.filter(l=>filterText(l.name,q.locations));
 const locationRows=locations.map((l,i)=>{const idx=state.locations.indexOf(l);return `<div class="settings-item settings-filter-row settings-locations-row" data-search="${esc(l.name)}"><input type="text" value="${esc(l.name)}" onchange="renameLocation(${idx},this.value)"></div>`}).join('')||'<div class="hint settings-empty">No matching locations.</div>';
 const cats=state.categories.filter(c=>(c.locationId||'nmdc-main')===loc&&filterText(c.name,q.categories));
 const catRows=cats.map(c=>{const i=state.categories.indexOf(c);return `<div class="settings-item settings-filter-row settings-categories-row" data-search="${esc(c.name)}"><input type="text" value="${esc(c.name)}" onchange="renameCategory(${i},this.value)"><select onchange="setCategoryType(${i},this.value)"><option value="income" ${c.type==='income'?'selected':''}>Income</option><option value="expense" ${c.type==='expense'?'selected':''}>Expense</option></select><select onchange="setCategoryLocation(${i},this.value)" title="Branch / Location">${state.locations.map(l=>`<option value="${l.id}" ${c.locationId===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select><select onchange="setCategoryLinkedList(${i},this.value)"><option value="none" ${c.linkedList==='none'?'selected':''}>No list</option><option value="employees" ${c.linkedList==='employees'?'selected':''}>Employees list</option><option value="vendors" ${c.linkedList==='vendors'?'selected':''}>Vendors list</option><option value="doctors" ${c.linkedList==='doctors'?'selected':''}>Doctors list</option>${state.customLists.map(x=>`<option value="custom:${x.id}" ${c.linkedList===('custom:'+x.id)?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button class="icon-btn" onclick="removeCategory(${i})">Remove</button></div>`}).join('')||'<div class="hint settings-empty">No matching categories.</div>';
 const accountSearch=String(q.accounts||'').trim();
 const accountRole=state.settingsAccountRole||'all',accountLoc=state.settingsAccountLocation||'all';
 const showAccounts=!!accountSearch||accountRole!=='all'||accountLoc!=='all';
 const userRows=showAccounts?(state.staff.filter(u=>{const hit=!accountSearch||filterText(u.name,accountSearch)||filterText(u.username,accountSearch);const roleOk=accountRole==='all'||u.role===accountRole;const locOk=accountLoc==='all'||u.locationId===accountLoc;return hit&&roleOk&&locOk}).map(u=>`<div class="settings-item settings-filter-row settings-accounts-row" data-search="${esc(u.name)} ${esc(u.username)} ${esc(u.role)} ${esc(locationName(u.locationId))}"><span style="flex:1"><strong>${esc(u.name)}</strong> <span class="hint">(${esc(u.username)})</span> ${u.active===false?'<span class="badge role-admin" style="margin-left:6px">Inactive</span>':'<span class="badge" style="margin-left:6px">Active</span>'}</span><select onchange="setUserRole('${u.id}',this.value)"><option value="staff" ${u.role==='staff'?'selected':''}>Staff</option><option value="reviewer" ${u.role==='reviewer'?'selected':''}>Reviewer</option><option value="admin" ${u.role==='admin'?'selected':''}>Admin</option></select>${u.role==='staff'?`<select onchange="setUserLocation('${u.id}',this.value)"><option value="">Select location</option>${state.locations.map(l=>`<option value="${l.id}" ${u.locationId===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select>`:'<span class="badge role-admin">All locations</span>'}<button class="icon-btn" onclick="resetUserPassword('${u.id}')">Reset password</button>${u.id!==state.user.id&&u.id!=='admin'?`<button class="icon-btn" onclick="setUserActive('${u.id}',${u.active===false?'true':'false'})">${u.active===false?'Enable':'Disable'}</button><button class="icon-btn" onclick="removeUser('${u.id}')">Remove</button>`:''}</div>`).join('')||'<div class="hint settings-empty">No matching accounts.</div>'):'<div class="hint settings-empty">Use search or filters to find an account.</div>';
 const showEmp=String(q.employees||'').trim()||state.settingsEmployeeLocation&&state.settingsEmployeeLocation!=='all';
 const empLoc=state.settingsEmployeeLocation||'all';
 const empRows=showEmp?state.employees.filter(e=>{const p=detailFor(e);const hit=!q.employees||filterText(e,q.employees)||filterText(p.designation,q.employees)||filterText(p.department,q.employees);const locOk=empLoc==='all'||p.locationId===empLoc;return hit&&locOk}).map(e=>{const p=detailFor(e),active=p.active!==false;return `<div class="settings-item settings-filter-row settings-employees-row" data-search="${esc(e)} ${esc(p.designation||'')} ${esc(p.department||'')} ${esc(locationName(p.locationId))}"><div style="flex:1"><strong>${esc(e)}</strong><div class="hint">${esc(locationName(p.locationId))} · ${esc(p.department||'ALL')} · ${esc(p.designation||'—')} ${active?'':'· Inactive'}</div></div><button class="icon-btn" onclick="openEmployeeForm('${escapeHtml(e).replace(/'/g,'\\\'')}','view')">View</button><button class="icon-btn" onclick="openEmployeeForm('${escapeHtml(e).replace(/'/g,'\\\'')}','edit')">Edit</button><button class="icon-btn" onclick="toggleEmployeeActive('${escapeHtml(e).replace(/'/g,'\\\'')}',${active?'false':'true'})">${active?'Disable':'Enable'}</button><button class="icon-btn" onclick="deleteEmployeeMaster('${escapeHtml(e).replace(/'/g,'\\\'')}')">Delete</button></div>`}).join(''):'<div class="hint settings-empty">Use search or select a location to find employees.</div>';
 const doctors=state.doctors.filter(v=>filterText(v,q.doctors));
 const docRows=doctors.map(v=>{const i=state.doctors.indexOf(v);return `<div class="settings-item settings-filter-row settings-doctors-row" data-search="${esc(v)}"><input type="text" value="${esc(v)}" onchange="renameDoctor(${i},this.value)"><button class="icon-btn" onclick="removeDoctor(${i})">Remove</button></div>`}).join('')||'<div class="hint settings-empty">No matching doctors.</div>';
 const vendors=state.vendors.filter(v=>filterText(v,q.vendors));
 const vendRows=vendors.map(v=>{const i=state.vendors.indexOf(v);return `<div class="settings-item settings-filter-row settings-vendors-row" data-search="${esc(v)}"><input type="text" value="${esc(v)}" onchange="renameVendor(${i},this.value)"><button class="icon-btn" onclick="removeVendor(${i})">Remove</button></div>`}).join('')||'<div class="hint settings-empty">No matching vendors.</div>';
 const custom=state.customLists.filter(l=>filterText(l.name,q.customLists)||((l.items||[]).some(x=>filterText(x,q.customLists))));
 const customRows=custom.map(l=>{const li=state.customLists.indexOf(l);return `<div class="card settings-filter-row settings-customLists-row" data-search="${esc(l.name)} ${(l.items||[]).map(esc).join(' ')}" style="padding:11px"><div class="settings-item"><input type="text" value="${esc(l.name)}" onchange="renameCustomList(${li},this.value)"><button class="icon-btn" onclick="removeCustomList(${li})">Remove list</button></div><div class="settings-list" style="margin-top:8px">${(l.items||[]).filter(x=>filterText(l.name,q.customLists)||filterText(x,q.customLists)).map(item=>{const ii=l.items.indexOf(item);return `<div class="settings-item"><input type="text" value="${esc(item)}" onchange="renameCustomListItem(${li},${ii},this.value)"><button class="icon-btn" onclick="removeCustomListItem(${li},${ii})">Remove</button></div>`}).join('')||'<div class="hint">No matching items.</div>'}</div><div class="add-row"><input type="text" id="newCustomItem_${li}" placeholder="Add item" style="flex:1"><button class="btn secondary" onclick="addCustomListItem(${li})">Add item</button></div></div>`}).join('')||'<div class="hint settings-empty">No matching custom lists.</div>';
 const special=(state.specialCards||[]).filter(c=>filterText(c.name,q.specialCards));
 const specialRows=special.map(c=>{const i=state.specialCards.indexOf(c);return `<div class="card settings-filter-row settings-specialCards-row" data-search="${esc(c.name)} ${esc(c.behavior||'')}" style="padding:11px"><div class="settings-item"><input type="text" value="${esc(c.name)}" onchange="renameSpecialCard(${i},this.value)" style="flex:1"><span class="badge role-admin">${esc(c.behavior||'special')}</span></div><div class="hint" style="margin:8px 0 6px">Assigned locations</div><div class="add-row">${state.locations.map(l=>`<label style="display:flex;align-items:center;gap:6px"><input type="checkbox" ${((c.assignedLocationIds||[]).includes(l.id)?'checked':'')} onchange="toggleSpecialCardLocation(${i},'${l.id}',this.checked)">${esc(l.name)}</label>`).join('')}</div></div>`}).join('')||'<div class="hint settings-empty">No matching special cards.</div>';
 return `<div class="row"><div class="col" style="flex:2;min-width:420px">
 <div class="card"><div class="settings-section-head"><h3>Locations</h3></div>${sectionSearch('settingsSearchLocations','Search location...','locations')}<div class="settings-list">${locationRows}</div></div>
 <div class="card"><div class="settings-section-head"><h3>Categories</h3></div><div class="field" style="max-width:430px;margin-bottom:12px"><label>Choose location</label><select onchange="setSettingsLocation(this.value)">${state.locations.map(l=>`<option value="${l.id}" ${loc===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select></div>${sectionSearch('settingsSearchCategories','Search category...','categories')}<div class="hint" style="margin-bottom:10px">Each category is linked to one branch/location. Only linked categories use a person dropdown + Other.</div><div class="settings-list">${catRows}</div><div class="add-row"><input type="text" id="newCatName" placeholder="New category name" style="flex:1"><select id="newCatType"><option value="income">Income</option><option value="expense">Expense</option></select><button class="btn secondary" onclick="addCategory()">Add</button></div></div>
 <div class="card"><div class="settings-section-head"><h3>Staff, Reviewer & Admin Accounts</h3><button class="btn" onclick="openAccountForm()">＋ Add Account</button></div>${sectionSearch('settingsSearchAccounts','Search name / username...','accounts')}<div class="filters" style="margin:8px 0 12px"><label>Role</label><select onchange="setSettingsAccountRole(this.value)"><option value="all">All Roles</option><option value="staff" ${accountRole==='staff'?'selected':''}>Staff</option><option value="reviewer" ${accountRole==='reviewer'?'selected':''}>Reviewer</option><option value="admin" ${accountRole==='admin'?'selected':''}>Admin</option></select><label>Location</label><select onchange="setSettingsAccountLocation(this.value)"><option value="all">All Locations</option>${state.locations.map(l=>`<option value="${l.id}" ${accountLoc===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select></div><div class="settings-list">${userRows}</div></div>${passwordCard()}</div>
 <div class="col" style="min-width:280px">
 <div class="card"><div class="settings-section-head"><h3>Employees List</h3><button class="btn" onclick="openEmployeeForm('','add')">＋ Add Employee</button></div>${sectionSearch('settingsSearchEmployees','Search employee name...','employees')}<div class="filters" style="margin:8px 0 12px"><label>Location</label><select onchange="setSettingsEmployeeLocation(this.value)"><option value="all">All Locations</option>${state.locations.map(l=>`<option value="${l.id}" ${empLoc===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select></div><div class="settings-list">${empRows}</div></div>
 <div class="card"><div class="settings-section-head"><h3>Doctors List</h3><button class="btn secondary" onclick="addDoctorPrompt()">＋ Add Doctor</button></div>${sectionSearch('settingsSearchDoctors','Search doctor...','doctors')}<div class="settings-list">${docRows}</div></div>
 <div class="card"><div class="settings-section-head"><h3>Vendors List</h3><button class="btn secondary" onclick="addVendorPrompt()">＋ Add Vendor</button></div>${sectionSearch('settingsSearchVendors','Search vendor...','vendors')}<div class="settings-list">${vendRows}</div></div>
 <div class="card"><div class="settings-section-head"><h3>Custom Lists</h3><button class="btn secondary" onclick="addCustomListPrompt()">＋ Create List</button></div>${sectionSearch('settingsSearchCustomLists','Search list / item...','customLists')}<div class="hint" style="margin-bottom:10px">Create reusable lists and link them to categories.</div><div class="settings-list">${customRows}</div></div>
 <div class="card"><div class="settings-section-head"><h3>Special Cards & Location Assignment</h3></div>${sectionSearch('settingsSearchSpecialCards','Search special card...','specialCards')}<div class="settings-list">${specialRows}</div><div class="add-row"><input id="newSpecialCardName" placeholder="New special card name" style="flex:1"><button class="btn secondary" onclick="addSpecialCard()">Create card</button></div></div>
 </div></div>`;
}
function passwordCard(){return `<div class="card"><h3>Change my password</h3><div class="field" style="margin-bottom:10px"><label>Current password</label><input type="password" id="oldPass"></div><div class="field" style="margin-bottom:10px"><label>New password</label><input type="password" id="newPass"></div><button class="btn secondary" onclick="changeMyPassword()">Update password</button></div>`}
function renderFinance(){
 const d=state.financeData||{salaries:[],fixedExpenses:[],departmentSummary:[],financeAdjustments:[],employeeLoans:{}}; const profiles=state.employeeProfiles||[]; const month=state.financeMonth; const panel=state.financePanel||'input';
 const salaryData=(d.salaries||[]).filter(r=>state.financeSalaryLocation==='all'||r.locationId===state.financeSalaryLocation);
 const expenseData=(d.fixedExpenses||[]).filter(r=>state.financeExpenseLocation==='all'||r.locationId===state.financeExpenseLocation);
 const adjustmentData=(d.financeAdjustments||[]); const vendorData=adjustmentData.filter(r=>state.financeVendorLocation==='all'||r.locationId===state.financeVendorLocation); const referralData=adjustmentData.filter(r=>state.financeReferralLocation==='all'||r.locationId===state.financeReferralLocation);
 const salaryRows=salaryData.map((r,i)=>{const rec=r.record||{};const has=!!r.hasRecord;const inclusionKey=`${month}::${r.employee}`;const included=Object.prototype.hasOwnProperty.call(state.financePendingSalaryInclusions,inclusionKey)?state.financePendingSalaryInclusions[inclusionKey]:(has?(rec.salaryIncluded!==false):false);const loanDed=Number(rec.loanDeduction??r.loan?.installment??0);const remaining=Number(rec.loanRemainingAfter??Math.max(0,Number(r.loan?.remaining||0)-loanDed));return `<tr id="salary_row_${i}"><td><label style="display:flex;align-items:flex-start;gap:8px;cursor:pointer"><input type="checkbox" id="salaryInclude_${i}" ${included?'checked':''} onchange="previewSalaryInclusion(${i},this.checked)" style="margin-top:2px;width:16px;height:16px;accent-color:#0b78d0"><span><strong>${escapeHtml(r.employee)}</strong><div class="entry-sub-detail">${escapeHtml(locationName(r.locationId))} · ${escapeHtml(r.department)}</div></span></label></td><td class="amt">${money(r.salary||0)}</td><td class="amt">${money(r.advanceSalary||0)}</td><td><input class="finance-mini-input" type="number" min="0" step="1" id="abs_${i}" value="${has?Number(rec.absentDays||0):''}" placeholder="0" oninput="previewSalaryRow(${i});queueSalarySave(${i})"></td><td><input class="finance-mini-input" type="number" min="0" step="1" id="late_${i}" value="${has?Number(rec.lateDays||0):''}" placeholder="0" oninput="previewSalaryRow(${i});queueSalarySave(${i})"></td><td><input class="finance-mini-input" type="number" min="0" step="0.01" id="ded_${i}" value="${has?Number(rec.manualDeduction||0):''}" placeholder="0" oninput="previewSalaryRow(${i});queueSalarySave(${i})"></td><td><input class="finance-mini-input" type="number" min="0" step="0.01" id="loanDed_${i}" value="${loanDed||0}" placeholder="0" oninput="previewSalaryRow(${i});queueSalarySave(${i})"></td><td class="amt" id="remainingLoan_${i}">${money(remaining)}</td><td class="amt"><strong id="netSalary_${i}">${money(rec.netSalary||0)}</strong></td><td class="no-print"><button class="btn secondary" onclick="printSalarySlip(${i})">Salary Slip</button></td></tr>`}).join('')||'<tr><td colspan="10" class="muted-row">No employees found for this location.</td></tr>';
 const profileLoc=state.financeProfileLocation||'all', profileSearch=String(state.financeProfileSearch||'').trim().toLowerCase();
 const loanLoc=state.financeLoanLocation||'all', loanSearch=String(state.financeLoanSearch||'').trim().toLowerCase();
 const fixedLoc=state.financeFixedLocation||'all', fixedSearch=String(state.financeFixedSearch||'').trim().toLowerCase();
 const profileCandidates=(state.employees||[]).map((name,i)=>{const p=profiles.find(x=>x.employee===name)||{employee:name,locationId:state.locations[0]?.id||'',department:'ALL',designation:'',salary:0};return {name,i,p}});
 const profileVisible=profileCandidates.filter(x=>(profileLoc==='all'||x.p.locationId===profileLoc)&&(!profileSearch||x.name.toLowerCase().includes(profileSearch)||String(x.p.department||'').toLowerCase().includes(profileSearch)||String(x.p.designation||'').toLowerCase().includes(profileSearch)));
 const profileRows=profileVisible.map(({name,i,p})=>`<tr><td><strong>${escapeHtml(name)}</strong></td><td><select id="ep_loc_${i}">${state.locations.map(l=>`<option value="${l.id}" ${p.locationId===l.id?'selected':''}>${escapeHtml(l.name)}</option>`).join('')}</select></td><td><select id="ep_dep_${i}">${financeDepartmentOptions(p.department)}</select></td><td><input type="text" id="ep_des_${i}" value="${escapeHtml(p.designation||'')}" placeholder="Designation"></td><td><input type="number" min="0" step="0.01" id="ep_sal_${i}" value="${Number(p.salary||0)}"></td><td><button class="btn secondary" onclick="saveEmployeeProfile(${i})">Save</button></td></tr>`).join('') || `<tr><td colspan="6" class="muted-row">${profileLoc==='all'&&!profileSearch?'Select a location or search an employee to show the list.':'No matching employees found.'}</td></tr>`;
 const loanCandidates=(state.employees||[]).map((name,i)=>{const p=profiles.find(x=>x.employee===name)||{};const loan=d.employeeLoans?.[name]||{};const remaining=loan.amount?Number(d.loanBalances?.[name]??Math.max(0,Number(loan.amount)-Number(loan.paidInstallments||0)*Number(loan.installment||0))):0;return {name,i,p,loan,remaining}});
 const loanVisible=loanCandidates.filter(x=>(loanLoc==='all'||x.p.locationId===loanLoc)&&(!loanSearch||x.name.toLowerCase().includes(loanSearch)||String(x.loan.amount||'').includes(loanSearch)));
 const loanRows=loanVisible.map(({name,p,loan,remaining})=>`<tr><td><strong>${escapeHtml(name)}</strong><div class="entry-sub-detail">${escapeHtml(locationName(p.locationId))}</div></td><td>${loan.amount?money(loan.amount):'—'}</td><td>${loan.amount?money(loan.installment):'—'}</td><td>${loan.amount?Number(loan.paidInstallments||0):'—'}</td><td>${loan.amount?money(remaining):'—'}</td><td><button class="btn secondary" onclick="openLoanSetup('${escapeHtml(name).replace(/'/g,'&#39;')}')">${loan.amount?'Edit Loan':'Set Loan'}</button></td></tr>`).join('') || `<tr><td colspan="6" class="muted-row">${loanLoc==='all'&&!loanSearch?'Select a location or search an employee to show the loan list.':'No matching employees found.'}</td></tr>`;
 const fixedCandidates=(state.fixedExpenseCategories||[]).filter(c=>c.active!==false).map((c,i)=>({c,i}));
 const fixedVisible=fixedCandidates.filter(x=>(fixedLoc==='all'||x.c.locationId===fixedLoc)&&(!fixedSearch||String(x.c.name||'').toLowerCase().includes(fixedSearch)||String(x.c.department||'').toLowerCase().includes(fixedSearch)));
 const categoryRows=fixedVisible.map(({c,i})=>`<tr><td><input id="fc_name_${i}" value="${escapeHtml(c.name)}"></td><td><select id="fc_loc_${i}">${state.locations.map(l=>`<option value="${l.id}" ${c.locationId===l.id?'selected':''}>${escapeHtml(l.name)}</option>`).join('')}</select></td><td><select id="fc_dep_${i}">${financeDepartmentOptions(c.department)}</select></td><td><button class="btn secondary" onclick="saveFixedCategory(${i})">Save</button> <button class="btn danger" onclick="removeFixedCategory(${i})">Disable</button></td></tr>`).join('') || `<tr><td colspan="4" class="muted-row">${fixedLoc==='all'&&!fixedSearch?'Select a location or search a fixed expense category to show the list.':'No matching fixed expense categories found.'}</td></tr>`;
 const fixedRows=expenseData.map((r,i)=>`<tr><td><strong>${escapeHtml(r.name)}</strong></td><td>${escapeHtml(locationName(r.locationId))}</td><td>${escapeHtml(r.department)}</td><td><input class="finance-amount-input" type="number" min="0" step="0.01" id="fx_${i}" value="${Number(r.amount||0)}"></td><td><button class="btn secondary" onclick="saveFixedAmount(${i})">Save</button></td></tr>`).join('')||'<tr><td colspan="5" class="muted-row">No fixed expense categories for this location.</td></tr>';
 const ds=(d.departmentSummary||[]).map(x=>`<tr><td>${escapeHtml(x.location)}</td><td>${escapeHtml(x.department)}</td><td class="amt">${money(x.revenue)}</td><td class="amt neg">− ${money(x.salary)}</td><td class="amt neg">− ${money(x.fixedExpense)}</td><td class="amt neg">− ${money(x.vendorPayment)}</td><td class="amt neg">− ${money(x.referralDoctorShare)}</td><td class="amt neg">− ${money(x.cashCounterExpense)}</td><td class="amt"><strong>${money(x.net)}</strong></td></tr>`).join('')||'<tr><td colspan="9" class="muted-row">No revenue/expense allocation data for this month.</td></tr>';
 const tabs=`<div class="finance-subtabs"><button class="${panel==='settings'?'active':''}" onclick="setFinancePanel('settings')">Settings</button><button class="${panel==='input'?'active':''}" onclick="setFinancePanel('input')">Monthly Input / Processing</button><button class="${panel==='report'?'active':''}" onclick="setFinancePanel('report')">Financial Dashboard</button></div>`;
 const monthTools=`<div class="filters" style="display:flex;align-items:center;gap:8px"><label>Month</label><input type="month" value="${month}" onchange="setFinanceMonth(this.value)"><button class="btn secondary" type="button" onclick="downloadMonthlySalaryPDF()">Download PDF</button><button class="btn primary" type="button" onclick="saveSalaryInclusions()">Save</button></div>`;
 const locationFilter=(id,value,fn)=>`<div class="filters" style="margin:8px 0 12px"><label>Location</label><select id="${id}" onchange="${fn}(this.value)"><option value="all" ${value==='all'?'selected':''}>All Locations</option>${state.locations.map(l=>`<option value="${l.id}" ${value===l.id?'selected':''}>${escapeHtml(l.name)}</option>`).join('')}</select></div>`;
 let body='';
 if(panel==='settings') body=`<div class="card"><div class="finance-panel-head"><div><h3>Employee Profile & Salary Setup</h3><div class="hint">Set employee location, department, designation and monthly salary once. Employee names always come from Settings → Employees.</div></div><button class="btn secondary" onclick="downloadEmployeeProfilePDF()">Download PDF</button></div><div class="filters" style="margin:10px 0 12px"><label>Location</label><select onchange="setFinanceProfileLocation(this.value)"><option value="all" ${profileLoc==='all'?'selected':''}>All Locations</option>${state.locations.map(l=>`<option value="${l.id}" ${profileLoc===l.id?'selected':''}>${escapeHtml(l.name)}</option>`).join('')}</select><input id="financeProfileSearch" value="${escapeHtml(state.financeProfileSearch||'')}" placeholder="🔍 Search employee / department / designation..." oninput="setFinanceSettingsSearch('profile',this.value)" style="flex:1"></div><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Location</th><th>Department</th><th>Designation</th><th>Monthly Salary</th><th>Action</th></tr></thead><tbody>${profileRows}</tbody></table></div></div><div class="card"><div class="finance-panel-head"><div><h3>Loan Setup</h3><div class="hint">Set an existing or new employee loan. Enter the total loan, monthly installment and installments already paid.</div></div><button class="btn" onclick="openLoanSetup('')">+ Loan Setup</button></div><div class="filters" style="margin:10px 0 12px"><label>Location</label><select onchange="setFinanceLoanLocation(this.value)"><option value="all" ${loanLoc==='all'?'selected':''}>All Locations</option>${state.locations.map(l=>`<option value="${l.id}" ${loanLoc===l.id?'selected':''}>${escapeHtml(l.name)}</option>`).join('')}</select><input id="financeLoanSearch" value="${escapeHtml(state.financeLoanSearch||'')}" placeholder="🔍 Search employee..." oninput="setFinanceSettingsSearch('loan',this.value)" style="flex:1"></div><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Loan Amount</th><th>Monthly Installment</th><th>Installments Paid</th><th>Remaining Loan</th><th>Action</th></tr></thead><tbody>${loanRows}</tbody></table></div></div><div class="card"><div class="finance-panel-head"><div><h3>Fixed Expense Categories</h3><div class="hint">Create and configure fixed expenses by location and department. These settings automatically appear in Monthly Input and Reports.</div></div></div><div class="filters" style="margin:10px 0 12px"><label>Location</label><select onchange="setFinanceFixedLocation(this.value)"><option value="all" ${fixedLoc==='all'?'selected':''}>All Locations</option>${state.locations.map(l=>`<option value="${l.id}" ${fixedLoc===l.id?'selected':''}>${escapeHtml(l.name)}</option>`).join('')}</select><input id="financeFixedSearch" value="${escapeHtml(state.financeFixedSearch||'')}" placeholder="🔍 Search fixed expense category..." oninput="setFinanceSettingsSearch('fixed',this.value)" style="flex:1"></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Location</th><th>Department</th><th>Action</th></tr></thead><tbody>${categoryRows}</tbody></table></div><div class="add-row" style="margin-top:12px"><input id="newFixedName" placeholder="New fixed expense name" style="flex:1"><select id="newFixedLoc">${state.locations.map(l=>`<option value="${l.id}">${escapeHtml(l.name)}</option>`).join('')}</select><select id="newFixedDep">${financeDepartmentOptions('ALL')}</select><button class="btn secondary" onclick="addFixedCategory()">Add Category</button></div></div>`;
 else if(panel==='report') { const fs=d.financialSummary||[]; const selected=state.financeDashboardLocation||'all'; const rows=fs.filter(x=>selected==='all'||x.locationId===selected); const total=rows.reduce((a,x)=>({revenue:a.revenue+x.revenue,salary:a.salary+x.salary,utilities:a.utilities+x.utilities,vendor:a.vendor+x.vendor,referral:a.referral+x.referral,cash:a.cash+x.cash,net:a.net+x.net}),{revenue:0,salary:0,utilities:0,vendor:0,referral:0,cash:0,net:0}); const totalExpenses=total.salary+total.utilities+total.vendor+total.referral+total.cash; body=`<div class="card"><div class="finance-panel-head"><div><h3>Financial Dashboard — ${escapeHtml(fmtMonthLabel(month))}</h3><div class="hint">Total Revenue = Laboratory + X-Ray + Ultrasound. Management expenses and Cash Counter Expenses are deducted to calculate Net Profit.</div></div>${monthTools}</div>${locationFilter('financeDashboardLocation',selected,'setFinanceDashboardLocation')}</div><div class="finance-dashboard-total"><div><div class="label">Total Revenue</div><div class="hint">Laboratory + X-Ray + Ultrasound</div></div><div class="value">${money(total.revenue)}</div></div><div class="finance-dashboard-grid"><div class="finance-dashboard-card expense"><div class="label">Salary Expense</div><div class="value">${money(total.salary)}</div></div><div class="finance-dashboard-card expense"><div class="label">Utilities & Rent</div><div class="value">${money(total.utilities)}</div></div><div class="finance-dashboard-card expense"><div class="label">Vendor Payment</div><div class="value">${money(total.vendor)}</div></div><div class="finance-dashboard-card expense"><div class="label">Referral Doctor Share</div><div class="value">${money(total.referral)}</div></div><div class="finance-dashboard-card expense"><div class="label">Cash Counter Expenses</div><div class="value">${money(total.cash)}</div></div><div class="finance-dashboard-card expense"><div class="label">Total Expenses</div><div class="value">${money(totalExpenses)}</div></div><div class="finance-dashboard-card profit"><div class="label">Net Profit</div><div class="value">${money(total.net)}</div></div></div><div class="card"><div class="section-head blue"><div class="section-title-left"><span class="section-icon">▤</span><span>Location-wise Financial Summary</span></div><div class="section-total">${selected==='all'?'All Locations':escapeHtml(locationName(selected))}</div></div><div class="table-wrap"><table><thead><tr><th>Location</th><th class="amt">Revenue</th><th class="amt">Salary</th><th class="amt">Utilities & Rent</th><th class="amt">Vendor Payment</th><th class="amt">Referral Doctor Share</th><th class="amt">Cash Counter Expenses</th><th class="amt">Net Profit</th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${escapeHtml(x.location)}</strong></td><td class="amt">${money(x.revenue)}</td><td class="amt neg">− ${money(x.salary)}</td><td class="amt neg">− ${money(x.utilities)}</td><td class="amt neg">− ${money(x.vendor)}</td><td class="amt neg">− ${money(x.referral)}</td><td class="amt neg">− ${money(x.cash)}</td><td class="amt"><strong>${money(x.net)}</strong></td></tr>`).join('')||'<tr><td colspan="8" class="muted-row">No financial data for this month.</td></tr>'}</tbody></table></div></div>`; }
 else body=`<div class="card"><div class="finance-panel-head"><div><h3>Monthly Salary Processing — ${escapeHtml(fmtMonthLabel(month))}</h3><div class="hint">Basic Salary − Advance − Deduction − Loan Deduction = Net Salary. Tick/untick employees, then click Save beside the month to save salary inclusion.</div></div>${monthTools}</div>${locationFilter('salaryLocationFilter',state.financeSalaryLocation,'setFinanceSalaryLocation')}<div class="table-wrap"><table><thead><tr><th>Employee (Include)</th><th class="amt">Basic Salary</th><th class="amt">Advance</th><th>Absent</th><th>Late</th><th>Deduction</th><th class="amt">Loan Deduction</th><th class="amt">Remaining Loan</th><th class="amt">Net Salary</th><th class="no-print">Action</th></tr></thead><tbody>${salaryRows}</tbody></table></div><div class="finance-total-bar"><span>Total Salary Expense</span><strong id="salaryTotalExpense">${money(salaryData.reduce((a,r)=>{const k=`${month}::${r.employee}`;const inc=Object.prototype.hasOwnProperty.call(state.financePendingSalaryInclusions,k)?state.financePendingSalaryInclusions[k]:(r.hasRecord?(r.record?.salaryIncluded!==false):false);return a+(inc?Number(r.record?.netSalary||0):0)},0))}</strong></div></div><div class="card"><div class="finance-panel-head"><div><h3>Monthly Utilities & Rent — ${escapeHtml(fmtMonthLabel(month))}</h3><div class="hint">Enter actual monthly amounts. Location filter also applies to Vendor Payment and Referral Doctor Share below.</div></div></div>${locationFilter('expenseLocationFilter',state.financeExpenseLocation,'setFinanceExpenseLocation')}<div class="table-wrap"><table><thead><tr><th>Expense</th><th>Location</th><th>Department</th><th>Amount</th><th>Action</th></tr></thead><tbody>${fixedRows}</tbody></table></div><div class="finance-total-bar"><span>Total Utilities & Rent</span><strong>${money(expenseData.reduce((a,r)=>a+Number(r.amount||0),0))}</strong></div></div><div class="card"><div class="finance-panel-head"><div><h3>Monthly Vendor Amount — ${escapeHtml(fmtMonthLabel(month))}</h3><div class="hint">Enter monthly vendor payments by location and department.</div></div></div>${locationFilter('vendorLocationFilter',state.financeVendorLocation,'setFinanceVendorLocation')}<div class="table-wrap"><table><thead><tr><th>Expense</th><th>Location</th><th>Department</th><th class="amt">Amount</th><th>Action</th></tr></thead><tbody>${vendorData.map((a,i)=>`<tr><td><strong>Vendor Payment</strong></td><td>${escapeHtml(a.location)}</td><td>ALL</td><td class="amt"><input class="finance-amount-input" type="number" min="0" step="0.01" id="vendor_${i}" value="${Number(a.vendorPayment||0)}"></td><td><button class="btn secondary" onclick="saveFinanceAdjustment('${a.locationId}','vendorPayment',${i})">Save</button></td></tr>`).join('')||'<tr><td colspan="5" class="muted-row">No locations available.</td></tr>'}</tbody></table></div><div class="finance-total-bar"><span>Total Vendor Amount</span><strong>${money(vendorData.reduce((a,r)=>a+Number(r.vendorPayment||0),0))}</strong></div></div><div class="card"><div class="finance-panel-head"><div><h3>Monthly Referral Doctor Amount — ${escapeHtml(fmtMonthLabel(month))}</h3><div class="hint">Enter monthly referral doctor share by location and department.</div></div></div>${locationFilter('referralLocationFilter',state.financeReferralLocation,'setFinanceReferralLocation')}<div class="table-wrap"><table><thead><tr><th>Expense</th><th>Location</th><th>Department</th><th class="amt">Amount</th><th>Action</th></tr></thead><tbody>${referralData.map((a,i)=>`<tr><td><strong>Referral Doctor Share</strong></td><td>${escapeHtml(a.location)}</td><td>ALL</td><td class="amt"><input class="finance-amount-input" type="number" min="0" step="0.01" id="referral_${i}" value="${Number(a.referralDoctorShare||0)}"></td><td><button class="btn secondary" onclick="saveFinanceAdjustment('${a.locationId}','referralDoctorShare',${i})">Save</button></td></tr>`).join('')||'<tr><td colspan="5" class="muted-row">No locations available.</td></tr>'}</tbody></table></div><div class="finance-total-bar"><span>Total Referral Doctor Amount</span><strong>${money(referralData.reduce((a,r)=>a+Number(r.referralDoctorShare||0),0))}</strong></div></div>`;
 return `<div class="card finance-page"><div class="analysis-head"><div><h2>Salary & Fixed Expenses</h2><div class="hint">Manage setup, monthly inputs and generated financial reports in separate sections.</div></div></div>${tabs}${body}</div>`;
}
window.setFinancePanel=function(panel){if(!['settings','input','report'].includes(panel))panel='input';state.financePanel=panel;render()};
window.setFinanceProfileLocation=function(v){state.financeProfileLocation=v||'all';render()};
window.setFinanceLoanLocation=function(v){state.financeLoanLocation=v||'all';render()};
window.setFinanceFixedLocation=function(v){state.financeFixedLocation=v||'all';render()};
window.liveSettingsSearch=function(key,value){state.settingsSearch=state.settingsSearch||{};state.settingsSearch[key]=value;const cls={employees:'settings-employees-row',accounts:'settings-accounts-row',locations:'settings-locations-row',categories:'settings-categories-row',doctors:'settings-doctors-row',vendors:'settings-vendors-row',customLists:'settings-customLists-row',specialCards:'settings-specialCards-row',fixedCategories:'settings-fixedCategories-row'}[key];if(!cls)return;const needle=String(value||'').trim().toLowerCase();const rows=[...document.querySelectorAll('.'+cls)];if((!needle)&&(key==='employees'||key==='accounts')){render();setTimeout(()=>{const el=document.getElementById(key==='employees'?'settingsSearchEmployees':'settingsSearchAccounts');if(el){el.focus();el.setSelectionRange(0,0)}},0);return}if(!rows.length&&needle&&(key==='employees'||key==='accounts')){render();setTimeout(()=>{const el=document.getElementById(key==='employees'?'settingsSearchEmployees':'settingsSearchAccounts');if(el){el.focus();el.setSelectionRange(el.value.length,el.value.length)}},0);return}rows.forEach(row=>{const hay=String(row.dataset.search||row.textContent||'').toLowerCase();row.style.display=!needle||hay.includes(needle)?'':'none'});};
window.filterSettingsSection=function(key,value){liveSettingsSearch(key,value)};
window.setSettingsEmployeeLocation=function(v){state.settingsEmployeeLocation=v;render()};
window.setSettingsAccountRole=function(v){state.settingsAccountRole=v;render()};
window.setSettingsAccountLocation=function(v){state.settingsAccountLocation=v;render()};
window.openEmployeeForm=function(employee='',mode='add'){state.modal={kind:'employeeForm',employee,mode};render();setTimeout(()=>document.getElementById('employee_name')?.focus(),30)};
window.openAccountForm=function(){state.modal={kind:'accountForm'};render();setTimeout(()=>document.getElementById('account_name')?.focus(),30)};
window.saveEmployeeMaster=async function(){const oldName=state.modal?.employee||'';const name=document.getElementById('employee_name')?.value.trim()||'',department=document.getElementById('employee_department')?.value||'ALL',designation=document.getElementById('employee_designation')?.value.trim()||'',dateOfJoining=document.getElementById('employee_doj')?.value||'',accountNumber=document.getElementById('employee_account')?.value.trim()||'';if(!name){showToast('Enter employee full name.',true);return}try{if(state.modal?.mode==='add'){const r=await api('/api/config/employee','POST',{name,department,designation,dateOfJoining,accountNumber});state.employees=r.employees||state.employees;state.employeeDetails=r.employeeDetails||state.employeeDetails;state.modal=null;await loadFinance();render();showToast('Employee added.')}else{const r=await api('/api/config/employee/'+encodeURIComponent(oldName),'PUT',{name,department,designation,dateOfJoining,accountNumber});state.employees=r.employees||state.employees;state.employeeDetails=r.employeeDetails||state.employeeDetails;state.employeeProfiles=r.employeeProfiles||state.employeeProfiles;state.modal=null;await loadFinance();render();showToast('Employee updated.')}}catch(e){showToast(e.message,true)}};
window.toggleEmployeeActive=async function(name,active){if(!confirm(`${active?'Enable':'Disable'} ${name}? ${active?'The employee will return to active salary/loan lists.':'The employee will be kept in history but removed from active salary/loan processing.'}`))return;try{const r=await api('/api/config/employee/'+encodeURIComponent(name)+'/status','PUT',{active});state.employeeDetails=r.employeeDetails||state.employeeDetails;state.employeeProfiles=r.employeeProfiles||state.employeeProfiles;await loadFinance();render();showToast(`Employee ${active?'enabled':'disabled'}.`)}catch(e){showToast(e.message,true)}};
window.deleteEmployeeMaster=async function(name){if(!confirm(`Delete ${name} from the active Employees list? Historical salary and financial records will be preserved.`))return;try{const r=await api('/api/config/employee/'+encodeURIComponent(name),'DELETE');state.employees=r.employees||state.employees;state.employeeDetails=r.employeeDetails||state.employeeDetails;state.employeeProfiles=r.employeeProfiles||state.employeeProfiles;await loadFinance();render();showToast('Employee removed from active list.')}catch(e){showToast(e.message,true)}};
window.addDoctorPrompt=async function(){const n=prompt('Doctor name:');if(!n?.trim())return;state.doctors.push(n.trim());await cfgPut('/api/config/doctors','doctors',state.doctors)};
window.addVendorPrompt=async function(){const n=prompt('Vendor name:');if(!n?.trim())return;state.vendors.push(n.trim());await cfgPut('/api/config/vendors','vendors',state.vendors)};
window.addCustomListPrompt=async function(){const n=prompt('New list name:');if(!n?.trim())return;state.customLists.push({id:n.trim().toLowerCase().replace(/[^a-z0-9]+/g,'_')+'_'+Math.random().toString(36).slice(2,7),name:n.trim(),items:[]});await cfgPut('/api/config/custom-lists','customLists',state.customLists)};
window.saveNewAccount=async function(){const name=document.getElementById('account_name')?.value.trim()||'',username=document.getElementById('account_username')?.value.trim()||'',password=document.getElementById('account_password')?.value||'',role=document.getElementById('account_role')?.value||'staff',locationId=document.getElementById('account_location')?.value||'';if(!name||!username||!password){showToast('Fill name, username and password.',true);return}if(role==='staff'&&!locationId){showToast('Select a location for Staff.',true);return}try{await api('/api/users','POST',{name,username,password,role,locationId});state.modal=null;await loadConfig();render();showToast('Account created.')}catch(e){showToast(e.message,true)}};
window.setFinanceSettingsSearch=function(type,value){if(type==='profile')state.financeProfileSearch=value||'';else if(type==='loan')state.financeLoanSearch=value||'';else if(type==='fixed')state.financeFixedSearch=value||'';render();requestAnimationFrame(()=>{const id=type==='profile'?'financeProfileSearch':type==='loan'?'financeLoanSearch':'financeFixedSearch';const el=document.getElementById(id);if(el){el.focus();const n=el.value.length;try{el.setSelectionRange(n,n)}catch(_){}}});};
window.setFinanceVendorLocation=function(v){state.financeVendorLocation=v;render()};
window.setFinanceReferralLocation=function(v){state.financeReferralLocation=v;render()};
window.setFinanceDashboardLocation=function(v){state.financeDashboardLocation=v;render()};
async function loadFinance(){try{state.financeData=await api('/api/finance-management?month='+encodeURIComponent(state.financeMonth)+'&locationId=all');state.employeeProfiles=state.financeData.employeeProfiles||state.employeeProfiles;state.fixedExpenseCategories=state.financeData.fixedExpenseCategories||state.fixedExpenseCategories;render()}catch(e){showToast(e.message,true)}}
window.setFinanceMonth=async function(v){if(!v)return;state.financeMonth=v;state.financePendingSalaryInclusions={};await loadFinance()};
window.setFinanceSalaryLocation=function(v){state.financeSalaryLocation=v;render()};
window.setFinanceExpenseLocation=function(v){state.financeExpenseLocation=v;render()};
window.saveEmployeeProfile=async function(i){const name=state.employees[i];if(!name)return;const existing=(state.employeeProfiles||[]).find(p=>p.employee===name)||{};const profiles=(state.employeeProfiles||[]).filter(p=>p.employee!==name);profiles.push({employee:name,locationId:document.getElementById('ep_loc_'+i).value,department:document.getElementById('ep_dep_'+i).value,designation:String(document.getElementById('ep_des_'+i)?.value||'').trim(),salary:Number(document.getElementById('ep_sal_'+i).value||0),sickLeaveEntitlement:Number(existing.sickLeaveEntitlement||0),casualLeaveEntitlement:Number(existing.casualLeaveEntitlement||0),annualLeaveEntitlement:Number(existing.annualLeaveEntitlement||0),active:true});try{const r=await api('/api/config/employee-profiles','PUT',{employeeProfiles:profiles});state.employeeProfiles=r.employeeProfiles||profiles;showToast('Employee profile saved.');await loadFinance()}catch(e){showToast(e.message,true)}};
window.saveLeaveEntitlements=async function(i){const name=state.employees[i];if(!name)return;const existing=(state.employeeProfiles||[]).find(p=>p.employee===name)||{employee:name,locationId:state.locations[0]?.id||'',department:'ALL',salary:0};const profiles=(state.employeeProfiles||[]).filter(p=>p.employee!==name);profiles.push({...existing,sickLeaveEntitlement:Number(document.getElementById('sick_ent_'+i).value||0),casualLeaveEntitlement:Number(document.getElementById('casual_ent_'+i).value||0),annualLeaveEntitlement:Number(document.getElementById('annual_ent_'+i).value||0),active:true});try{const r=await api('/api/config/employee-profiles','PUT',{employeeProfiles:profiles});state.employeeProfiles=r.employeeProfiles||profiles;showToast('Leave entitlement saved.');await loadFinance()}catch(e){showToast(e.message,true)}};
window.openLoanSetup=function(employee=''){state.modal={kind:'loanSetup',employee};render();setTimeout(()=>document.getElementById('loan_amount')?.focus(),30)};
window.loadLoanForm=function(employee){state.modal=state.modal||{};state.modal.employee=employee;const loan=state.financeData?.employeeLoans?.[employee]||{};const set=(id,v)=>{const el=document.getElementById(id);if(el)el.value=v??''};set('loan_amount',loan.amount||'');set('loan_installment',loan.installment||'');set('loan_paid',Number(loan.paidInstallments||0));set('loan_remarks',loan.remarks||'');updateLoanFormRemaining()};
window.updateLoanFormRemaining=function(){const amount=Number(document.getElementById('loan_amount')?.value||0),inst=Number(document.getElementById('loan_installment')?.value||0),paid=Math.max(0,Math.floor(Number(document.getElementById('loan_paid')?.value||0)));const el=document.getElementById('loan_remaining_preview');if(el)el.textContent=money(Math.max(0,amount-paid*inst))};
window.saveEmployeeLoan=async function(){const employee=document.getElementById('loan_employee')?.value,amount=Number(document.getElementById('loan_amount')?.value||0),installment=Number(document.getElementById('loan_installment')?.value||0),paidInstallments=Math.max(0,Math.floor(Number(document.getElementById('loan_paid')?.value||0))),remarks=document.getElementById('loan_remarks')?.value||'';if(!employee||amount<=0||installment<=0){showToast('Enter employee, loan amount and monthly installment.',true);return}if(paidInstallments>Math.ceil(amount/installment)){showToast('Paid installments cannot be greater than the loan.',true);return}try{await api('/api/finance-management/employee-loan','PUT',{employee,amount,installment,paidInstallments,startMonth:state.financeMonth,remarks});state.modal=null;await loadFinance()}catch(e){showToast(e.message,true)}};
window.removeEmployeeLoan=async function(employee){if(!confirm('Remove this employee loan?'))return;try{await api('/api/finance-management/employee-loan/'+encodeURIComponent(employee),'DELETE',{});state.modal=null;await loadFinance()}catch(e){showToast(e.message,true)}};
const salarySaveTimers={};
window.previewSalaryRow=function(i){const r=(state.financeData?.salaries||[]).filter(x=>state.financeSalaryLocation==='all'||x.locationId===state.financeSalaryLocation)[i];if(!r)return;const basic=Number(r.salary||0),advance=Number(r.advanceSalary||0),ded=Number(document.getElementById('ded_'+i)?.value||0),loanDed=Number(document.getElementById('loanDed_'+i)?.value||0),maxLoan=Number(r.loan?.remaining||0),safeLoan=Math.min(Math.max(0,loanDed),Math.max(0,maxLoan));const net=Math.max(0,basic-advance-ded-safeLoan),remaining=Math.max(0,maxLoan-safeLoan);const n=document.getElementById('netSalary_'+i),rem=document.getElementById('remainingLoan_'+i);if(n)n.textContent=money(net);if(rem)rem.textContent=money(remaining)};
window.queueSalarySave=function(i){clearTimeout(salarySaveTimers[i]);salarySaveTimers[i]=setTimeout(()=>saveSalaryRow(i),650)};
window.previewSalaryInclusion=function(i,checked){
  const rows=(state.financeData?.salaries||[]).filter(x=>state.financeSalaryLocation==='all'||x.locationId===state.financeSalaryLocation);
  const r=rows[i]; if(!r)return;
  const key=`${state.financeMonth}::${r.employee}`;
  state.financePendingSalaryInclusions[key]=!!checked;
  const total=rows.reduce((sum,x)=>{
    const k=`${state.financeMonth}::${x.employee}`;
    const included=Object.prototype.hasOwnProperty.call(state.financePendingSalaryInclusions,k)?state.financePendingSalaryInclusions[k]:(x.hasRecord?(x.record?.salaryIncluded!==false):false);
    return sum+(included?Number(x.record?.netSalary||0):0);
  },0);
  const totalEl=document.getElementById('salaryTotalExpense'); if(totalEl) totalEl.textContent=money(total);
};
window.saveSalaryInclusions=async function(){
  const rows=(state.financeData?.salaries||[]).filter(x=>state.financeSalaryLocation==='all'||x.locationId===state.financeSalaryLocation);
  if(!rows.length){showToast('No salary employees found.',true);return;}
  const selections=rows.map((r,i)=>({employee:r.employee,salaryIncluded:!!document.getElementById(`salaryInclude_${i}`)?.checked}));
  try{
    await api('/api/finance-management/salary-inclusions','PUT',{month:state.financeMonth,selections});
    state.financePendingSalaryInclusions={};
    showToast('Salary selections saved.');
    await loadFinance();
  }catch(e){showToast('Salary selections were not saved. '+e.message,true);}
};

window.saveSalaryRow=async function(i){const r=(state.financeData?.salaries||[]).filter(x=>state.financeSalaryLocation==='all'||x.locationId===state.financeSalaryLocation)[i];if(!r)return;const loanEl=document.getElementById('loanDed_'+i);const loanDed=Math.max(0,Number(loanEl?.value||0));try{const resp=await api('/api/finance-management/salary','PUT',{month:state.financeMonth,employee:r.employee,absentDays:Number(document.getElementById('abs_'+i)?.value||0),lateDays:Number(document.getElementById('late_'+i)?.value||0),manualDeduction:Number(document.getElementById('ded_'+i)?.value||0),loanDeduction:loanDed});const rows=state.financeData?.salaries||[];const current=rows.find(x=>x.employee===r.employee&&x.locationId===r.locationId);if(current){current.hasRecord=true;current.record=resp.record;current.loan=current.loan||r.loan} }catch(e){showToast('Salary update was not saved. '+e.message,true)}};
window.saveFixedAmount=async function(i){const rows=(state.financeData?.fixedExpenses||[]).filter(x=>state.financeExpenseLocation==='all'||x.locationId===state.financeExpenseLocation),r=rows[i];if(!r)return;try{await api('/api/finance-management/fixed-expense','PUT',{month:state.financeMonth,categoryId:r.id,amount:Number(document.getElementById('fx_'+i).value||0)});showToast('Fixed expense saved.');await loadFinance()}catch(e){showToast(e.message,true)}};
window.saveFinanceAdjustment=async function(locationId,type,i){const id=type==='vendorPayment'?'vendor_'+i:'referral_'+i;const amount=Number(document.getElementById(id)?.value||0);try{await api('/api/finance-management/adjustment','PUT',{month:state.financeMonth,locationId,type,amount});showToast(type==='vendorPayment'?'Vendor payment saved.':'Referral doctor share saved.');await loadFinance()}catch(e){showToast(e.message,true)}};
window.printSalarySlip=function(i){const rows=(state.financeData?.salaries||[]).filter(x=>state.financeSalaryLocation==='all'||x.locationId===state.financeSalaryLocation),r=rows[i];if(!r)return;const rec=r.record||{},basic=Number(rec.basicSalary||r.salary||0),adv=Number(rec.advanceSalary||r.advanceSalary||0),ded=Number(rec.manualDeduction||0),loanDed=Number(rec.loanDeduction??r.loan?.installment??0),net=Number(rec.netSalary||Math.max(0,basic-adv-ded-loanDed));const w=window.open('','_blank','width=850,height=850');if(!w){showToast('Please allow pop-ups to print the salary slip.',true);return}w.document.write(`<!doctype html><html><head><title>Salary Slip</title><style>body{font-family:Arial,sans-serif;padding:35px;color:#17324d}h1{text-align:center;margin:0 0 4px}h2{text-align:center;font-size:16px;margin:0 0 20px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:8px 30px;border:1px solid #ccc;padding:12px}.box{border:1px solid #bbb;margin-top:20px}.box h3{margin:0;padding:8px;background:#f3f6fa;font-size:14px}.row{display:flex;justify-content:space-between;padding:9px 10px;border-bottom:1px solid #ddd}.total{font-weight:700;font-size:17px}.sign{display:grid;grid-template-columns:1fr 1fr;gap:80px;margin-top:80px;text-align:center}.line{border-top:1px solid #333;padding-top:6px}small{color:#666}</style></head><body><h1>Lab-Brain</h1><h2>Salary Slip — ${escapeHtml(fmtMonthLabel(state.financeMonth))}</h2><div class="meta"><div><b>Employee:</b> ${escapeHtml(r.employee)}</div><div><b>Location:</b> ${escapeHtml(locationName(r.locationId))}</div><div><b>Department:</b> ${escapeHtml(r.department)}</div><div><b>Pay Period:</b> ${escapeHtml(fmtMonthLabel(state.financeMonth))}</div></div><div class="box"><h3>Salary</h3><div class="row"><span>Basic Salary</span><span>${money(basic)}</span></div><div class="row"><span>Advance</span><span>${money(adv)}</span></div><div class="row"><span>Deduction</span><span>${money(ded)}</span></div><div class="row"><span>Loan Deduction</span><span>${money(loanDed)}</span></div><div class="row total"><span>Net Salary</span><span>${money(net)}</span></div></div><div class="box"><h3>Loan</h3><div class="row"><span>Total Loan</span><span>${money(r.loan?.amount||0)}</span></div><div class="row"><span>Monthly Installment</span><span>${money(loanDed)}</span></div><div class="row"><span>Remaining Loan</span><span>${money(rec.loanRemainingAfter??r.loan?.remaining??0)}</span></div></div><div class="sign"><div class="line">Employer Signature</div><div class="line">Employee Signature</div></div><p style="text-align:center;margin-top:35px"><small>This is a system generated payslip.</small></p><script>window.onload=function(){window.print();}<\/script></body></html>`);w.document.close()};

window.addFixedCategory=async function(){const name=document.getElementById('newFixedName').value.trim();if(!name){showToast('Enter a fixed expense name.',true);return}const arr=[...(state.fixedExpenseCategories||[]),{id:'fixed_'+Date.now(),name,locationId:document.getElementById('newFixedLoc').value,department:document.getElementById('newFixedDep').value,active:true}];try{const r=await api('/api/config/fixed-expense-categories','PUT',{fixedExpenseCategories:arr});state.fixedExpenseCategories=r.fixedExpenseCategories||arr;showToast('Fixed expense category added.');await loadFinance()}catch(e){showToast(e.message,true)}};
window.saveFixedCategory=async function(i){const active=(state.fixedExpenseCategories||[]).filter(c=>c.active!==false),c=active[i];if(!c)return;c.name=document.getElementById('fc_name_'+i).value.trim();c.locationId=document.getElementById('fc_loc_'+i).value;c.department=document.getElementById('fc_dep_'+i).value;try{const all=[...(state.fixedExpenseCategories||[])].map(x=>x.id===c.id?c:x);const r=await api('/api/config/fixed-expense-categories','PUT',{fixedExpenseCategories:all});state.fixedExpenseCategories=r.fixedExpenseCategories||all;showToast('Fixed expense category saved.');await loadFinance()}catch(e){showToast(e.message,true)}};
window.removeFixedCategory=async function(i){const active=(state.fixedExpenseCategories||[]).filter(c=>c.active!==false),c=active[i];if(!c||!confirm('Disable this fixed expense category? Existing monthly amounts will remain saved.'))return;const all=[...(state.fixedExpenseCategories||[])].map(x=>x.id===c.id?{...x,active:false}:x);try{const r=await api('/api/config/fixed-expense-categories','PUT',{fixedExpenseCategories:all});state.fixedExpenseCategories=r.fixedExpenseCategories||all;showToast('Category disabled.');await loadFinance()}catch(e){showToast(e.message,true)}};

window.setUserActive=async function(id,active){const u=(state.staff||[]).find(x=>x.id===id);if(!u)return;if(!confirm(`${active?'Enable':'Disable'} ${u.name}'s account? ${active?'They will be able to log in again.':'They will no longer be able to log in, and AI checks will stop expecting activity after the effective date.'}`))return;try{await api('/api/users/'+id,'PUT',{active});await loadConfig();render();showToast(`Account ${active?'enabled':'disabled'}.`)}catch(e){showToast(e.message,true)}};

(async()=>{try{const ok=await tryResume();if(ok){state.loading=true;render();await loadEverything();const q=new URLSearchParams(location.search);const aiDate=q.get('aiDate');if(aiDate){state.currentDate=aiDate;state.selectedLocation=q.get('aiLocation')||'all';state.selectedUser=q.get('aiUser')||'all';state.view='today';state.reportSubpage='overview';await loadDayData(aiDate);render();history.replaceState({},'',location.pathname)}}else{state.loading=false;render()}}catch(e){console.error('Startup failed:',e);state.token=null;state.user=null;localStorage.removeItem('labbrain_token');localStorage.removeItem('roznamcha_token');state.loading=false;state.loginError='Unable to load the previous session. Please log in again.';render()}})();


